// ── POST /api/growth/referral/register ────────────────────────────────────────
// Associates the current logged-in user (referee) with the referrer's referral code.
// Called automatically on dashboard or onboarding mount if a referral code is found in localStorage.
export async function POST(req: NextRequest) {
  try {
    const user = await getSession()
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

    const { code } = await req.json()
    if (!code) {
      return NextResponse.json({ error: "Referral code is required" }, { status: 400 })
    }

    const cleanCode = code.trim().toUpperCase()

    // 1. Check if the user has already been referred (refereeId is unique in Referral)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const alreadyReferred = await (prisma as any).referral.findFirst({
      where: { refereeId: user.id },
    })

    if (alreadyReferred) {
      return NextResponse.json({
        ok: true,
        message: "User is already associated with a referral link",
        referral: alreadyReferred,
      })
    }

    // 2. Find the referrer's master referral link
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const referrerRecord = await (prisma as any).referral.findFirst({
      where: { referralCode: cleanCode },
    })

    if (!referrerRecord) {
      return NextResponse.json({ error: "Invalid referral code" }, { status: 404 })
    }

    // A user cannot refer themselves
    if (referrerRecord.referrerId === user.id) {
      return NextResponse.json({ error: "You cannot refer yourself" }, { status: 400 })
    }

    // 3. Create a new referral record for this relation
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const newReferral = await (prisma as any).referral.create({
      data: {
        referrerId: referrerRecord.referrerId,
        refereeId: user.id,
        referralCode: cleanCode,
        referralLink: referrerRecord.referralLink,
        status: "SIGNED_UP",
        signedUpAt: new Date(),
      },
    })

    // 4. Log a Growth Event
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (prisma as any).growthEvent.create({
      data: {
        userId: user.id,
        type: "referral_signed_up",
        channel: referrerRecord.channel || "direct",
        metadata: {
          referrerId: referrerRecord.referrerId,
          referralCode: cleanCode,
        },
      },
    })

    return NextResponse.json({
      ok: true,
      message: "Referral registered successfully",
      referral: newReferral,
    })
  } catch (error) {
    console.error("[POST /api/growth/referral/register]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import prisma from "@/lib/prisma"
import { getSession } from "@/lib/auth-checks"

// ── Referral code generator ───────────────────────────────────────────────────
function generateReferralCode(name: string, userId: string): string {
  const namePart = (name || "USER").replace(/\s+/g, "").toUpperCase().slice(0, 5)
  const idPart = userId.replace(/-/g, "").slice(0, 4).toUpperCase()
  return `${namePart}${idPart}`
}

// ── GET /api/growth/referral — fetch or create my referral link ───────────────
export async function GET() {
  try {
    const user = await getSession()
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const existing = await (prisma as any).referral.findFirst({
      where: { referrerId: user.id },
      orderBy: { createdAt: "asc" },
    })

    if (existing) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const allReferrals: any[] = await (prisma as any).referral.findMany({
        where: { referrerId: user.id },
        orderBy: { createdAt: "desc" },
      })

      const stats = {
        totalSent: allReferrals.length,
        signedUp: allReferrals.filter((r: any) => r.status !== "PENDING").length,
        converted: allReferrals.filter((r: any) => r.status === "CONVERTED" || r.status === "REWARDED").length,
        rewarded: allReferrals.filter((r: any) => r.status === "REWARDED").length,
        totalCashEarned: allReferrals.reduce((sum: number, r: any) => sum + (r.referrerCash || 0), 0),
        conversionRate: allReferrals.length > 0
          ? Math.round((allReferrals.filter((r: any) => r.status === "CONVERTED" || r.status === "REWARDED").length / allReferrals.length) * 100)
          : 0,
      }

      return NextResponse.json({
        referralCode: existing.referralCode,
        referralLink: existing.referralLink,
        stats,
        recentReferrals: allReferrals.slice(0, 5),
      })
    }

    // Create new referral record (the "master" link for this user)
    const dbUser = await prisma.user.findUnique({ where: { id: user.id }, select: { name: true } })
    const code = generateReferralCode(dbUser?.name || "USER", user.id)
    const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "https://campusconnectco.in"
    const link = `${baseUrl}/join?ref=${code}&utm_source=referral&utm_medium=share&utm_campaign=student_referral`

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const created = await (prisma as any).referral.create({
      data: {
        referrerId: user.id,
        referralCode: code,
        referralLink: link,
        status: "PENDING",
      },
    })

    return NextResponse.json({
      referralCode: created.referralCode,
      referralLink: created.referralLink,
      stats: { totalSent: 0, signedUp: 0, converted: 0, rewarded: 0, totalCashEarned: 0, conversionRate: 0 },
      recentReferrals: [],
    })
  } catch (error) {
    console.error("[GET /api/growth/referral]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

// ── POST /api/growth/referral — track a share event ──────────────────────────
export async function POST(req: NextRequest) {
  try {
    const user = await getSession()
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 })

    const { channel } = await req.json()

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    await (prisma as any).growthEvent.create({
      data: {
        userId: user.id,
        type: "referral_sent",
        channel: channel || "unknown",
        metadata: { timestamp: new Date().toISOString() },
      },
    })

    return NextResponse.json({ ok: true })
  } catch (error) {
    console.error("[POST /api/growth/referral]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from "next/server"
import prisma from "@/lib/prisma"

// ── GET /api/growth/share-card — generate shareable card metadata ─────────────
// Called by the frontend after a milestone is hit
// Returns the data needed to render the OG share image + deeplink
export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url)
    const type = searchParams.get("type") || "first_gig"
    const userId = searchParams.get("userId") || ""

    if (!userId) return NextResponse.json({ error: "userId required" }, { status: 400 })

    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { name: true, image: true, college: true, username: true },
    })

    if (!user) return NextResponse.json({ error: "User not found" }, { status: 404 })

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let gamif: any = null
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      gamif = await (prisma as any).userGamification.findUnique({ where: { userId } })
    } catch { /* optional */ }

    const firstName = user.name?.split(" ")[0] || "A student"
    const college = user.college || "India"
    const baseUrl = process.env.NEXT_PUBLIC_APP_URL || "https://campusconnectco.in"

    const CARD_TEMPLATES: Record<string, { headline: string; subtext: string; emoji: string }> = {
      first_gig:    { headline: `${firstName} just shipped their first gig 🚀`, subtext: `Building real work before graduation at CampusConnect`, emoji: "🚀" },
      earning_1k:   { headline: `${firstName} earned ₹1,000 as a student 💰`, subtext: `From ${college}. Real work. Real pay. No degree needed.`, emoji: "💰" },
      earning_5k:   { headline: `₹5,000 earned without a degree 🎯`, subtext: `${firstName} from ${college} is on CampusConnect`, emoji: "🎯" },
      earning_10k:  { headline: `₹10,000 milestone unlocked! 🏆`, subtext: `${firstName} proves students can earn before graduation`, emoji: "🏆" },
      earning_25k:  { headline: `₹25,000 earned as a student 🔥`, subtext: `${firstName} · ${college} · CampusConnect`, emoji: "🔥" },
      earning_1l:   { headline: `₹1 Lakh earned as a student 👑`, subtext: `${firstName} from ${college} just hit ₹1L on CampusConnect`, emoji: "👑" },
      streak_7:     { headline: `7-day streak 🔥 Nothing stopping ${firstName}`, subtext: `Daily career building at CampusConnect · ${college}`, emoji: "🔥" },
      streak_30:    { headline: `30-day streak! ${firstName} never stopped 💯`, subtext: `A month of consistent career building · ${college}`, emoji: "💯" },
      badge:        { headline: `${firstName} just earned a new badge ⭐`, subtext: `${college} student leveling up on CampusConnect`, emoji: "⭐" },
      rank_1:       { headline: `${firstName} is #1 on campus 👑`, subtext: `Top of the CampusConnect leaderboard at ${college}`, emoji: "👑" },
      level_up:     { headline: `Level ${gamif?.level || "up"}: ${gamif?.levelTitle || "Achieved"} 🎮`, subtext: `${firstName} from ${college} keeps leveling up`, emoji: "🎮" },
    }

    const template = CARD_TEMPLATES[type] || CARD_TEMPLATES["first_gig"]

    // Referral link embedded in the card
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    let referralCode: string | null = null
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const ref = await (prisma as any).referral.findFirst({ where: { referrerId: userId }, orderBy: { createdAt: "asc" } })
      referralCode = ref?.referralCode || null
    } catch { /* optional */ }

    const shareUrl = referralCode
      ? `${baseUrl}/join?ref=${referralCode}&utm_source=share_card&utm_medium=social&utm_campaign=${type}`
      : `${baseUrl}?utm_source=share_card&utm_medium=social&utm_campaign=${type}`

    // OG image URL (for dynamic image generation via /api/og/card)
    const ogImageUrl = `${baseUrl}/api/og/card?type=${type}&name=${encodeURIComponent(firstName)}&college=${encodeURIComponent(college)}&emoji=${template.emoji}`

    // Track the card generation
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      await (prisma as any).shareCard.create({
        data: {
          userId,
          type,
          metadata: { headline: template.headline, subtext: template.subtext, college, smartScore: gamif?.smartScore },
        },
      })
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      await (prisma as any).growthEvent.create({
        data: { userId, type: "share_card_generated", metadata: { cardType: type, college } },
      })
    } catch { /* non-blocking */ }

    // Pre-formatted share text per channel
    const shareText = {
      whatsapp: `${template.headline}\n\n${template.subtext}\n\n🔗 Join me: ${shareUrl}`,
      twitter: `${template.headline} ${template.subtext} ${shareUrl} #CampusConnect #StudentFreelancing`,
      linkedin: `${template.headline}\n\n${template.subtext}\n\nJoin 10,000+ students building verified careers: ${shareUrl}`,
      instagram: `${template.headline}\n${template.subtext}\n\n👉 Link in bio`,
    }

    return NextResponse.json({
      template,
      shareUrl,
      ogImageUrl,
      shareText,
      referralCode,
      userName: firstName,
      college,
    })
  } catch (error) {
    console.error("[GET /api/growth/share-card]", error)
    return NextResponse.json({ error: "Internal server error" }, { status: 500 })
  }
}

"use client"

import Image from "next/image"

import { useEffect, useState } from "react"
import { Card } from "@/components/ui/Card"
import { Button } from "@/components/ui/Button"
import { User, MessageSquare, Check, X, Clock, Sparkles, Loader2 } from "lucide-react"
import { toast } from "sonner"
import { useRouter } from "next/navigation"
import { motion, AnimatePresence } from "framer-motion"

export default function ClientApplicantsPage() {
    const router = useRouter()
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [applications, setApplications] = useState<any[]>([])
    const [loading, setLoading] = useState(true)


    useEffect(() => {
        fetch("/api/client-hub/applicants")
            .then(res => res.json())
            .then(data => {
                if (Array.isArray(data)) {
                    setApplications(data)
                }
            })
            .catch(err => {
                toast.error("Failed to load applicants")
                console.error(err)
            })
            .finally(() => setLoading(false))
    }, [])

    const handleStatusChange = async (applicationId: string, status: "ACCEPTED" | "REJECTED") => {
        try {
            const res = await fetch(`/api/applications/${applicationId}`, {
                method: "PATCH",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ status })
            })

            if (res.ok) {
                toast.success(status === "ACCEPTED" ? "Applicant hired successfully!" : "Application declined")
                setApplications(prev => prev.map(app => app.id === applicationId ? { ...app, status } : app))
            } else {
                toast.error("Failed to update status")
            }
        } catch {
            toast.error("An error occurred");
        }
    }

    const handleMessage = async (applicantId: string) => {
        try {
            const res = await fetch("/api/conversations", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ otherUserId: applicantId })
            })
            if (res.ok) {
                router.push(`/messages?userId=${applicantId}`)
            } else {
                toast.error("Unable to start conversation")
            }
        } catch {
            toast.error("Something went wrong.")
        }
    }

    if (loading) {
        return (
            <div className="flex h-[60vh] items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-(--primary)" />
            </div>
        )
    }

    return (
        <div className="space-y-8 max-w-5xl mx-auto pb-12">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <h2 className="font-black tracking-tight text-white">Review Applicants</h2>
                    <p className="text-slate-500 mt-2 font-medium">Manage and hire students who have applied to your gigs.</p>
                </div>
            </div>

            {applications.length === 0 ? (
                <div className="text-center py-20 bg-white/2 dark:bg-slate-900/40 rounded-3xl border border-white/10">
                    <User className="h-16 w-16 mx-auto text-slate-300 dark:text-slate-700 mb-4" />
                    <h3 className="font-black text-white mb-2">No Applicants Yet</h3>
                    <p className="text-slate-500 font-medium max-w-sm mx-auto">Applications for your posted gigs will appear here. Try sharing your gig links to attract more talent.</p>
                </div>
            ) : (
                <div className="grid gap-5">
                    <AnimatePresence>
                        {applications.map((application, idx) => {
                            const applicant = application.applicant
                            const gig = application.gig
                            const skillsStr = applicant.skills || "General"

                            const now = new Date().getTime();
                            const isNew = new Date(application.createdAt).getTime() > now - 86400000;

                            return (
                                <motion.div
                                    key={application.id}
                                    initial={{ opacity: 0, y: 10 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    transition={{ delay: idx * 0.05 }}
                                >
                                    <Card className={`p-6 rounded-3xl overflow-hidden transition-all ${application.status === 'ACCEPTED' ? 'bg-emerald-50/50 dark:bg-emerald-900/10 border-emerald-200 dark:border-emerald-800/50 shadow-sm' : application.status === 'REJECTED' ? 'opacity-60 dark:bg-slate-900/30 grayscale-50' : 'hover:shadow-lg dark:bg-slate-900 bg-white'}`}>
                                        <div className="flex flex-col md:flex-row md:items-start justify-between gap-6">

                                            {/* Applicant Info Section */}
                                            <div className="flex items-start gap-5 flex-1">
                                                <div className="h-14 w-14 shrink-0 rounded-2xl bg-(--primary)/10 border border-(--primary)/20 flex items-center justify-center text-(--primary) overflow-hidden shadow-inner">
                                                    {applicant.image ? (
                                                        <Image src={applicant.image} alt={applicant.name} className="w-full h-full object-cover" fill />
                                                    ) : (
                                                        <User size={24} />
                                                    )}
                                                </div>
                                                <div className="flex-1">
                                                    <div className="flex flex-wrap items-center gap-2.5 mb-1.5">
                                                        <h3 className="font-black text-white leading-none">{applicant.name || "Student"}</h3>
                                                        {application.status === 'PENDING' && isNew && (
                                                            <span className="bg-blue-100 dark:bg-blue-900/40 dark:text-blue-300 text-[10px] px-2 py-0.5 rounded-full font-black uppercase tracking-wider flex items-center gap-1">
                                                                <div className="w-1 h-1 rounded-full bg-blue-500 animate-pulse" /> New
                                                            </span>
                                                        )}
                                                        {application.status === 'ACCEPTED' && (
                                                            <span className="bg-emerald-100 dark:bg-emerald-900/40 dark:text-emerald-400 text-[10px] px-2 py-0.5 rounded-full font-black uppercase tracking-wider flex items-center gap-1 border border-emerald-200 dark:border-emerald-800/40">
                                                                <Check size={10} /> Hired
                                                            </span>
                                                        )}
                                                        {application.status === 'REJECTED' && (
                                                            <span className="bg-(--surface-2) dark:text-slate-400 text-[10px] px-2 py-0.5 rounded-full font-black uppercase tracking-wider">
                                                                Declined
                                                            </span>
                                                        )}
                                                    </div>
                                                    <p className="font-bold text-slate-600 dark:text-slate-400 mb-2">
                                                        Applied for: <span className="text-(--primary)">{gig.title}</span>
                                                    </p>
                                                    {application.coverLetter && (
                                                        <p className="font-medium text-slate-500 bg-(--surface-2) p-3 rounded-xl border border-white/5 dark:border-slate-700 mb-3 italic">
                                                            &quot;{application.coverLetter.length > 120 ? application.coverLetter.substring(0, 120) + "..." : application.coverLetter}&quot;
                                                        </p>
                                                    )}
                                                    <div className="flex flex-wrap items-center gap-3 font-bold text-slate-500">
                                                        <span className="flex items-center gap-1 text-slate-600 dark:text-slate-300"><Sparkles size={12} className="text-(--accent)" /> {skillsStr}</span>
                                                        <span className="flex items-center gap-1"><Clock size={12} /> {new Date(application.createdAt).toLocaleDateString()}</span>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Actions Section */}
                                            <div className="flex flex-col items-center gap-3 w-full md:w-[160px] shrink-0 pt-4 md:pt-0 border-white/5 md:border-t-0">
                                                <Button
                                                    variant="outline"
                                                    onClick={() => handleMessage(applicant.id)}
                                                    className="w-full h-10 rounded-xl font-bold border-white/10 hover:border-(--primary)/40 hover:bg-white/2 dark:hover:bg-slate-800 transition-all gap-2 shrink-0"
                                                >
                                                    <MessageSquare size={16} className="text-(--primary)" /> Message
                                                </Button>

                                                {application.status === 'ACCEPTED' && gig.status === 'OPEN' && (
                                                    <div className="w-full h-10 px-4 rounded-xl bg-emerald-600/20 border border-emerald-500/30 text-xs font-bold flex items-center justify-center gap-2">
                                                        ✓ Hired — Contact to get started
                                                    </div>
                                                )}

                                                {application.status === 'PENDING' && (
                                                    <div className="flex gap-2 w-full">
                                                        <Button
                                                            variant="outline"
                                                            onClick={() => handleStatusChange(application.id, "REJECTED")}
                                                            className="h-10 px-3 rounded-xl border-white/10 text-slate-400 hover:text-red-500 hover:border-red-200 hover:bg-red-50 dark:hover:border-red-900/50 dark:hover:bg-red-900/20 transition-all shrink-0"
                                                        >
                                                            <X size={18} />
                                                        </Button>
                                                        <Button
                                                            onClick={() => handleStatusChange(application.id, "ACCEPTED")}
                                                            className="flex-1 h-10 px-4 rounded-xl bg-(--primary) hover:bg-blue-600 text-white font-black shadow-lg shadow-electric/20 active:scale-95 transition-all gap-2"
                                                        >
                                                            Hire
                                                        </Button>
                                                    </div>
                                                )}
                                            </div>

                                        </div>
                                    </Card>
                                </motion.div>
                            )
                        })}
                    </AnimatePresence>
                </div>
            )}

        </div>
    )
}

