          <p className="text-slate-400">Unable to load your company settings. Please try again or refresh.</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-background">
      <StartupProfileEditor profile={profile} />
    </div>
  )
}

