    { icon: Users, label: "Users", href: "/dashboard/founder/users" },
    { icon: Briefcase, label: "Gigs", href: "/dashboard/founder/gigs" },
    { icon: GraduationCap, label: "Internships", href: "/dashboard/founder/internships" },
    { icon: FileText, label: "Applications", href: "/dashboard/founder/applications" },
    { icon: ShieldAlert, label: "Approvals", href: "/dashboard/founder/approvals" },
    { icon: BarChart, label: "Reports", href: "/dashboard/founder/reports" },
    { icon: BarChart, label: "Analytics", href: "/dashboard/founder/analytics" },
    { icon: ShieldAlert, label: "Moderation", href: "/dashboard/founder/moderation" },
    { icon: Brain, label: "AI Insights", href: "/dashboard/founder/ai-insights" },
    { icon: Bell, label: "Notifications", href: "/dashboard/founder/notifications" },
    { icon: Settings, label: "System Settings", href: "/dashboard/founder/settings" },
]


interface ClientLayoutProps {
    children: React.ReactNode;
    initialRole: string;
    isPreviewMode: boolean;
}

export default function ClientLayout({ children, initialRole, isPreviewMode }: ClientLayoutProps) {
    const pathname = usePathname()
    const router = useRouter()
    const [isSidebarOpen, setIsSidebarOpen] = useState(false)
    const [isSigningOut, setIsSigningOut] = useState(false)
    const [isNotificationsOpen, setIsNotificationsOpen] = useState(false)

    // Role is now passed from server (Requirement 8)
    const role = initialRole;

    const isStudentPath = pathname?.startsWith("/dashboard/student")
    const isFounderPath = pathname?.startsWith("/dashboard/founder")
    const isClientPath = pathname?.startsWith("/dashboard") && !isStudentPath && !isFounderPath

    // Dynamic Header Title
    const getHeaderTitle = () => {
        if (pathname === "/dashboard/student") return "Student Overview"
        if (pathname === "/dashboard") return "Dashboard"
        if (pathname?.includes("/internships")) return pathname.includes("/founder") ? "Internship Management" : "Internships"
        if (pathname?.includes("/applicants")) return "Applicants"
        if (pathname?.includes("/post-gig")) return "Post a new Gig"
        if (pathname?.includes("/gigs")) return pathname.includes("/founder") ? "Gig Operations" : "Browse Gigs"
        if (pathname?.includes("/applications")) return pathname.includes("/founder") ? "Platform Applications" : "My Applications"
        if (pathname?.includes("/profile")) return "Wall of Fame"
        if (pathname === "/dashboard/founder") return "Control Room"
        if (pathname?.includes("/analytics")) return "Platform Analytics"
        if (pathname?.includes("/users")) return "User Manager"
        if (pathname?.includes("/moderation")) return "Moderation Queue"
        if (pathname?.includes("/ai-insights")) return "AI Insights"
        if (pathname?.includes("/approvals")) return "Pending Approvals"
        if (pathname?.includes("/reports")) return "Platform Reports"
        if (pathname?.includes("/notifications")) return "System Notifications"
        if (pathname?.includes("/settings")) return "Platform Settings"
        if (pathname?.includes("/about")) return "Our Story"
        return "Dashboard"
    }

    const headerTitle = getHeaderTitle()

    const handleSignOut = async () => {
        setIsSigningOut(true)
        try {
            const supabase = createClient()
            await supabase.auth.signOut()
            toast.success("Signed out successfully")
            router.push("/auth/sign-in")
        } catch {
            toast.error("Failed to sign out")
        } finally {
            setIsSigningOut(false)
        }
    }

    const enterPreview = async () => {
        await fetch('/api/founder/preview', { method: 'POST', body: JSON.stringify({ enable: true }) });
        router.refresh(); // Important to refresh server components
        router.push('/dashboard/student');
    }

    const exitPreview = async () => {
        await fetch('/api/founder/preview', { method: 'POST', body: JSON.stringify({ enable: false }) });
        router.refresh();
        router.push('/dashboard/founder');
    }

    return (
        <div className="min-h-screen bg-background text-foreground relative overflow-hidden transition-colors duration-300">
            {/* 10. FOUNDER PREVIEW MODE LABEL (Requirement 10) */}
            {isPreviewMode && (
                <div className="bg-amber-400 px-4 py-2 text-center font-bold flex justify-between items-center shadow-md relative z-50">
                    <span className="flex items-center gap-2">
                        <Users size={16} />
                        PREVIEW MODE: You are viewing the platform as a student. Actions are restricted.
                    </span>
                    <Button size="sm" variant="secondary" onClick={exitPreview} className="bg-black text-white hover:bg-slate-800 border-none h-8">
                        Exit Preview
                    </Button>
                </div>
            )}

            {/* Mobile Sidebar Overlay */}
            <AnimatePresence>
                {isSidebarOpen && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        onClick={() => setIsSidebarOpen(false)}
                        className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 md:hidden"
                    />
                )}
            </AnimatePresence>

            {/* Sidebar */}
            <aside className={`w-64 fixed top-16 h-[calc(100vh-4rem)] z-40 transition-all duration-300 md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'} bg-[#0a0a0f]/80 backdrop-blur-xl border-white/5 shadow-[4px_0_24px_rgba(0,0,0,0.2)]`}>
                <div className="p-6 h-full flex flex-col">
                    <nav className="flex-1 space-y-6 overflow-y-auto custom-scrollbar pr-2">
                        {isStudentPath && (
                            <div className="space-y-2">
                                <p className="px-4 font-black text-slate-400 uppercase tracking-widest mb-2 opacity-70">Student Hub</p>
                                <div className="space-y-1">
                                    {studentItems.map((item) => (
                                        <SidebarLink key={item.href} {...item} isActive={pathname === item.href} />
                                    ))}
                                </div>
                            </div>
                        )}

                        {isClientPath && (
                            <div className="space-y-2">
                                <p className="px-4 font-black text-slate-400 uppercase tracking-widest mb-2 opacity-70">Client Hub</p>
                                <div className="space-y-1">
                                    {clientItems.map((item) => (
                                        <SidebarLink key={item.href} {...item} isActive={pathname === item.href} />
                                    ))}
                                </div>
                            </div>
                        )}

                        {isFounderPath && (
                            <div className="space-y-4">
                                <div className="space-y-2">
                                    <p className="px-4 font-black text-slate-400 uppercase tracking-widest mb-2 opacity-70">Founder Hub</p>
                                    <div className="space-y-1">
                                        {founderItems.map((item) => (
                                            <SidebarLink key={item.href} {...item} isActive={pathname === item.href} />
                                        ))}
                                    </div>
                                </div>
                                <div className="px-2">
                                    <Button
                                        onClick={enterPreview}
                                        variant="outline"
                                        className="w-full justify-start border-amber-500/50 text-amber-500 hover:bg-amber-500/10 gap-2 h-9"
                                    >
                                        <Users size={14} />
                                        View as Student
                                    </Button>
                                </div>
                            </div>
                        )}

                        {!isFounderPath && !isStudentPath && !isClientPath && (
                            <div className="space-y-2">
                                <p className="px-4 font-black text-slate-400 uppercase tracking-widest mb-2 opacity-70">Menu</p>
                                <SidebarLink icon={Home} label="Back to Dash" href={role === 'FOUNDER' ? '/dashboard/founder' : role === 'CLIENT' ? '/dashboard' : '/dashboard/student'} isActive={false} />
                            </div>
                        )}

                        <div className="pb-10 space-y-2">
                            <p className="px-4 font-black text-slate-400 uppercase tracking-widest mb-2 opacity-70">General</p>
                            <div className="space-y-1">
                                <SidebarLink icon={Info} label="Our Story" href="/about" isActive={pathname === '/about'} />
                                <SidebarLink
                                    icon={Settings}
                                    label="Settings"
                                    href={role === 'FOUNDER' ? '/dashboard/founder/settings' : role === 'CLIENT' ? '/dashboard/student/settings' : '/dashboard/student/settings'}
                                    isActive={pathname?.includes('/settings')}
                                />
                            </div>
                        </div>
                    </nav>

                    <div className="pt-6 border-white/10 mt-auto">
                        <Button
                            variant="ghost"
                            className="w-full justify-start text-red-500 hover:text-red-400 hover:bg-red-500/10 rounded-xl font-medium"
                            onClick={handleSignOut}
                            disabled={isSigningOut}
                        >
                            <LogOut size={18} className="mr-3" />
                            {isSigningOut ? "Signing Out..." : "Sign Out"}
                        </Button>
                    </div>
                </div>
            </aside>

            {/* Main Content */}
            <main className="flex-1 md:ml-64 w-full relative z-10 transition-all duration-300">
                <header className="h-16 bg-[#0a0a0f]/70 backdrop-blur-xl border-white/5 sticky top-0 z-30 px-4 md:px-8 flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-4">
                        <button
                            onClick={() => setIsSidebarOpen(true)}
                            className="p-2 -ml-2 text-slate-500 hover:bg-white/5 rounded-lg md:hidden transition-colors"
                        >
                            <Menu size={20} />
                        </button>
                        <h1 className="font-black md:text-base text-white tracking-tight flex items-center gap-3">
                            <span className="relative flex h-2.5 w-2.5">
                                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-(--primary) opacity-75"></span>
                                <span className="relative inline-flex rounded-full h-2.5 w-2.5 bg-(--primary)"></span>
                            </span>
                            {headerTitle}
                        </h1>
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="hidden sm:block font-black tracking-widest text-slate-500 bg-white/5 px-3 py-1.5 rounded-full border border-white/5">
                            {new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
                        </div>
                        <div className="h-6 w-px bg-white/5 mx-1" />
                        <PostGigModal />
                        <Link href="/dashboard/student/messages" className="relative p-2.5 rounded-full text-slate-500 hover:bg-white/5 transition-all duration-300">
                            <MessageCircle size={20} />
                        </Link>
                        <NotificationsPopover
                            isOpen={isNotificationsOpen}
                            onOpenChange={setIsNotificationsOpen}
                        />
                    </div>
                </header>

                <div className="p-4 md:p-8 max-w-7xl mx-auto min-h-[calc(100vh-4rem)]">
                    {children}
                </div>
            </main>
        </div>
    )
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function SidebarLink({ href, icon: Icon, label, isActive }: { href: string, icon: any, label: string, isActive: boolean }) {
    return (
        <Link href={href}>
            <div className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 ${isActive ? 'bg-blue-500/10 text-blue-400 font-bold shadow-sm' : 'text-slate-400 hover:bg-white/5 hover:text-white font-medium' }`}>
                <Icon size={18} className={isActive ? "text-blue-400" : ""} />
                <span className="text-xs md:text-sm tracking-wide">{label}</span>
                {isActive && (
                    <motion.div
                        className="ml-auto w-1.5 h-1.5 rounded-full bg-blue-400 shadow-[0_0_8px_rgba(96,165,250,0.5)]"
                    />
                )}
            </div>
        </Link>
    )
}

"use client";

import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import {
    BarChart2, Users, TrendingUp, Briefcase, MessageCircle,
    DollarSign, CheckCircle2, Star, Zap, RefreshCw, Crown
} from "lucide-react";
import FinancialChart from "@/components/Analytics/FinancialChart";

interface AnalyticsData {
    growth: { totalUsers: number; newUsers30d: number; growthRate: number };
    opportunities: {
        totalApplications: number;
        recentApplications30d: number;
        totalGigsCompleted: number;
        recentGigCompletions30d: number;
    };
    engagement: { activeConversations: number };
    monetization: { premiumGigs: number; featuredInternships: number; estimatedRevenue: number };
}

const containerVariants = {
    hidden: { opacity: 0 },
    show: { opacity: 1, transition: { staggerChildren: 0.07 } }
};
const cardVariants = {
    hidden: { opacity: 0, y: 20 },
    show: { opacity: 1, y: 0 }
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function StatCard({ icon: Icon, label, value, sub, color, bgColor }: any) {
    return (
        <motion.div variants={cardVariants}
            className="bg-(--surface) border border-white/10 rounded-2xl p-6 relative overflow-hidden group hover:border-white/20 transition-all">
            <div className={`absolute top-0 right-0 w-28 h-28 ${bgColor} blur-3xl rounded-full opacity-60`} />
            <div className={`p-2.5 rounded-xl ${bgColor} ${color} w-fit mb-4 relative z-10`}>
                <Icon size={20} />
            </div>
            <p className="font-bold text-slate-500 uppercase tracking-widest mb-1 relative z-10">{label}</p>
            <p className="font-black text-white relative z-10">{value}</p>
            {sub && <p className="text-slate-400 font-medium mt-1.5 relative z-10">{sub}</p>}
        </motion.div>
    );
}

export default function AnalyticsDashboard() {
    const [data, setData] = useState<AnalyticsData | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchAnalytics = async () => {
        setLoading(true);
        setError(null);
        try {
            const res = await fetch("/api/analytics/platform");
            if (!res.ok) {
                throw new Error(`Analytics API returned ${res.status}`);
            }
            const json = await res.json();
            setData(json);
        } catch (e: unknown) {
            setError((e as Error).message || "Failed to load analytics.");
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchAnalytics();
    }, []);

    if (loading) {
        return (
            <div className="space-y-6 animate-pulse">
                <div className="h-10 w-64 bg-(--surface-2) rounded-2xl" />
                <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                    {[...Array(8)].map((_, i) => (
                        <div key={i} className="h-32 bg-(--surface-2) rounded-2xl" />
                    ))}
                </div>
                <div className="h-80 bg-(--surface-2) rounded-2xl" />
            </div>
        );
    }

    if (error || !data) {
        return (
            <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="p-4 bg-red-500/10 text-red-400 rounded-2xl mb-4">
                    <BarChart2 size={32} />
                </div>
                <h2 className="font-bold text-white mb-2">Analytics Unavailable</h2>
                <p className="text-sm mb-6 max-w-sm">{error || "Could not load platform data."}</p>
                <button onClick={fetchAnalytics}
                    className="flex items-center gap-2 px-5 py-2.5 font-bold rounded-xl transition-colors text-sm" style={{ background: "var(--color-primary)" }}>
                    <RefreshCw size={14} /> Retry
                </button>
            </div>
        );
    }

    const stats = [
        { icon: Users, label: "Total Students", value: data.growth.totalUsers.toLocaleString(), sub: `+${data.growth.newUsers30d} this month`, color: "text-blue-400", bgColor: "bg-blue-500/10" },
        { icon: TrendingUp, label: "Growth Rate (30d)", value: `${data.growth.growthRate.toFixed(1)}%`, sub: "Monthly new student growth", color: "text-orange-400", bgColor: "bg-(--primary)/10" },
        { icon: Briefcase, label: "Total Applications", value: data.opportunities.totalApplications.toLocaleString(), sub: `+${data.opportunities.recentApplications30d} last 30 days`, color: "text-purple-400", bgColor: "bg-purple-500/10" },
        { icon: CheckCircle2, label: "Gigs Completed", value: data.opportunities.totalGigsCompleted.toLocaleString(), sub: `+${data.opportunities.recentGigCompletions30d} recently`, color: "text-emerald-400", bgColor: "bg-emerald-500/10" },
        { icon: MessageCircle, label: "Active Conversations", value: data.engagement.activeConversations.toLocaleString(), sub: "Live student-founder chats", color: "text-teal-400", bgColor: "bg-teal-500/10" },
        { icon: Star, label: "Premium Gigs", value: data.monetization.premiumGigs.toLocaleString(), sub: "Paid featured listings", color: "text-amber-400", bgColor: "bg-(--accent)/10" },
        { icon: Crown, label: "Featured Internships", value: data.monetization.featuredInternships.toLocaleString(), sub: "Premium placement slots", color: "text-orange-400", bgColor: "bg-(--primary)/10" },
        { icon: DollarSign, label: "Est. Revenue", value: `₹${data.monetization.estimatedRevenue.toLocaleString()}`, sub: "From monetization features", color: "text-rose-400", bgColor: "bg-rose-500/10" },
    ];

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-10">
            {/* Header */}
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
                <div>
                    <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-full bg-(--surface-2) border border-white/10 text-xs font-bold uppercase tracking-wider mb-3">
                        <Zap size={12} className="text-orange-400" /> Live Data
                    </div>
                    <h1 className="md:text-4xl font-black text-white tracking-tight flex items-center gap-3" style={{ fontFamily: "var(--font-display)" }}>
                        <BarChart2 style={{ color: "var(--color-primary)" }} size={32} />
                        Platform <span style={{ color: "var(--color-primary)" }}>Analytics</span>
                    </h1>
                    <p className="text-slate-400 font-medium mt-1">Real-time intelligence — student growth, marketplace activity, and revenue metrics.</p>
                </div>
                <button onClick={fetchAnalytics}
                    className="flex items-center gap-2 px-5 py-2.5 bg-(--surface-2) hover:bg-white/10 border border-white/10 font-bold text-sm rounded-xl transition-all self-start md:self-auto">
                    <RefreshCw size={14} /> Refresh
                </button>
            </div>

            {/* Stats Grid */}
            <motion.div variants={containerVariants} initial="hidden" animate="show"
                className="grid grid-cols-2 md:grid-cols-4 gap-4">
                {stats.map((s, i) => <StatCard key={i} {...s} />)}
            </motion.div>

            {/* Revenue Chart */}
            <motion.div variants={cardVariants} initial="hidden" animate="show"
                className="bg-(--surface) border border-white/10 rounded-3xl p-4 md:p-8 shadow-xl">
                <div className="flex items-center gap-3 mb-6 pb-5 border-white/5">
                    <div className="p-2.5 bg-emerald-500/10 text-emerald-400 rounded-xl"><DollarSign size={20} /></div>
                    <div>
                        <h2 className="font-black text-white">Revenue Growth & Escrow Timeline</h2>
                        <p className="font-bold text-slate-500">Historical escrow & platform fee over time</p>
                    </div>
                </div>
                <div className="h-80">
                    <FinancialChart />
                </div>
            </motion.div>

            {/* Monetization Summary */}
            <motion.div variants={cardVariants} initial="hidden" animate="show"
                className="bg-(--surface) border border-white/10 rounded-3xl p-4 md:p-8 shadow-xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-(--accent)/5 blur-3xl rounded-full" />
                <div className="flex items-center gap-3 mb-6 pb-5 border-white/5 relative z-10">
                    <div className="p-2.5 bg-(--accent)/10 text-amber-400 rounded-xl"><Crown size={20} /></div>
                    <div>
                        <h2 className="font-black text-white">Monetization Overview</h2>
                        <p className="font-bold text-slate-500">Premium listings & projected platform earnings</p>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 relative z-10">
                    {[
                        { label: "Basic Listing", desc: "Free — unlimited", value: "Free", tag: "Default", c: "bg-white/20/10 text-slate-400 border-slate-500/20" },
                        { label: "Featured Listing", desc: "Highlighted in search results", value: "₹499/listing", tag: "Popular", c: "bg-(--primary)/10 text-orange-400 border-(--primary)/20" },
                        { label: "Premium Placement", desc: "Homepage & AI SmartMatch boost", value: "₹999/listing", tag: "Best ROI", c: "bg-(--accent)/10 text-amber-400 border-amber-500/20" },
                    ].map((tier, i) => (
                        <div key={i} className={`p-5 rounded-2xl border ${tier.c} flex flex-col gap-3`}>
                            <span className={`text-[10px] font-bold uppercase tracking-widest px-2.5 py-1 rounded-lg w-fit border ${tier.c}`}>{tier.tag}</span>
                            <h3 className="font-bold text-lg">{tier.label}</h3>
                            <p className="text-slate-400">{tier.desc}</p>
                            <p className="font-black text-white mt-auto">{tier.value}</p>
                        </div>
                    ))}
                </div>
            </motion.div>
        </div>
    );
}

import { protectPage } from "@/lib/auth-checks";
import prisma from "@/lib/prisma";
import { FileText } from "lucide-react";
import { redirect } from "next/navigation";
import { Card } from "@/components/ui/Card";
import Link from "next/link";

export default async function ApplicationsOverviewPage() {
    const { authorized } = await protectPage(["FOUNDER"]);

    if (!authorized) {
        redirect("/dashboard");
    }

    const applications = await prisma.application.findMany({
        orderBy: { createdAt: "desc" },
        take: 30, // Most recent applications
        include: {
            applicant: { select: { name: true, email: true } },
            gig: { select: { title: true, budget: true, poster: { select: { name: true } } } }
        }
    });

    return (
        <div className="space-y-8 animate-in fade-in duration-500 pb-10">
            <div>
                <h1 className="md:text-4xl font-black text-white tracking-tight flex items-center gap-3">
                    <FileText className="text-orange-500" size={32} />
                    Platform <span className="text-orange-500">Applications</span>
                </h1>
                <p className="text-slate-500 font-medium mt-1">Recent gig and internship applications across the platform.</p>
            </div>

            <div className="bg-[#111116] rounded-3xl p-4 md:p-8 shadow-2xl border border-white/10 relative overflow-hidden group">
                <div className="absolute inset-0 bg-linear-to-br from-orange-500/5 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none" />

                <div className="overflow-x-auto relative z-10">
                    <table className="w-full text-left">
                        <thead>
                            <tr className="border-white/5 font-black uppercase tracking-widest text-slate-500">
                                <th className="pb-6 pr-4">Applicant</th>
                                <th className="pb-6 px-4">Opportunity</th>
                                <th className="pb-6 px-4">Poster</th>
                                <th className="pb-6 px-4">Status</th>
                                <th className="pb-6 px-4">Time</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {applications.map((app) => (
                                <tr key={app.id} className="hover:bg-white/2 transition-colors group/row">
                                    <td className="py-5 pr-4">
                                        <div className="flex items-center gap-3">
                                            <div className="w-8 h-8 rounded-lg bg-orange-500/10 flex items-center justify-center font-black text-xs">
                                                {app.applicant.name?.charAt(0) || "U"}
                                            </div>
                                            <div>
                                                <p className="font-bold text-sm group-hover/row:text-orange-400 transition-colors">
                                                    {app.applicant.name || app.applicant.email}
                                                </p>
                                                <p className="text-slate-500 font-medium">{app.applicant.email}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="py-5 px-4">
                                        <Link href={`/gigs/${app.gig?.title ? app.gigId : ""}`} className="font-bold hover:text-orange-500 transition-colors line-clamp-1 text-sm underline decoration-white/10 underline-offset-4">
                                            {app.gig?.title || "Unknown Gig"}
                                        </Link>
                                    </td>
                                    <td className="py-5 px-4">
                                        <p className="text-sm font-medium">{app.gig?.poster?.name || "Unknown"}</p>
                                    </td>
                                    <td className="py-5 px-4">
                                        <span className={`px-2.5 py-1 rounded-lg font-black uppercase tracking-widest border ${app.status === 'HIRED' || app.status === 'ACCEPTED' ? 'bg-emerald-500/10' : app.status === 'REJECTED' ? 'bg-rose-500/10' : 'bg-orange-500/10 text-orange-400 border-orange-500/20' }`}>
                                            {app.status}
                                        </span>
                                    </td>
                                    <td className="py-5 px-4 text-right">
                                        <p className="text-[10px] font-black uppercase tracking-widest">
                                            {new Date(app.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
                                        </p>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                    {applications.length === 0 && (
                        <div className="text-center py-10">
                            <FileText size={48} className="mx-auto text-slate-700 mb-3" />
                            <p className="text-slate-500 font-medium">No applications found.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import {
    Briefcase,
    Search,
    CheckCircle,
    XCircle,
    AlertTriangle,
    Eye,
    Clock,
    DollarSign,
    Calendar,
} from "lucide-react";
import { motion } from "framer-motion";

interface Gig {
    id: string;
    title: string;
    description: string;
    budget: number;
    deadline: Date | null;
    status: string;
    tags: string | null;
    createdAt: Date;
    poster: {
        name: string | null;
        email: string;
    };
    _count: {
        applications: number;
    };
}

export default function GigModerationPage() {
    const [gigs, setGigs] = useState<Gig[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");
    const [statusFilter, setStatusFilter] = useState("all");
    const [stats, setStats] = useState({
        total: 0,
        open: 0,
        closed: 0,
        pending: 0,
    });

    useEffect(() => {
        loadGigs();
    }, []);

    const loadGigs = async () => {
        try {
            const response = await fetch("/api/founder/gigs");
            if (!response.ok) throw new Error("Failed to fetch gigs");

            const data = await response.json();
            setGigs(data.gigs || []);
            setStats(data.stats || { total: 0, open: 0, closed: 0, pending: 0 });
        } catch (error) {
            console.error("Error loading gigs:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleGigAction = async (gigId: string, action: string) => {
        try {
            const response = await fetch(`/api/founder/gigs/${gigId}`, {
                method: "PATCH",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ action }),
            });

            if (!response.ok) throw new Error("Failed to perform action");

            // Reload gigs
            loadGigs();
        } catch (error) {
            console.error("Error performing action:", error);
            alert("Failed to perform action");
        }
    };

    const filteredGigs = gigs.filter((gig) => {
        const matchesSearch =
            gig.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            gig.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
            gig.poster.email.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesStatus = statusFilter === "all" || gig.status === statusFilter;
        return matchesSearch && matchesStatus;
    });

    return (
        <div className="min-h-screen pt-20 pb-12">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                {/* Header */}
                <div className="mb-8">
                    <h1 className="md:text-4xl font-black text-white mb-2">
                        Gig Moderation
                    </h1>
                    <p className="text-slate-400">
                        Review and moderate all gigs posted on the platform
                    </p>
                </div>

                {/* Stats */}
                <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                    <StatCard
                        icon={Briefcase}
                        label="Total Gigs"
                        value={stats.total}
                        color="blue"
                    />
                    <StatCard
                        icon={CheckCircle}
                        label="Open"
                        value={stats.open}
                        color="green"
                    />
                    <StatCard
                        icon={XCircle}
                        label="Closed"
                        value={stats.closed}
                        color="red"
                    />
                    <StatCard
                        icon={Clock}
                        label="Pending"
                        value={stats.pending}
                        color="amber"
                    />
                </div>

                {/* Filters */}
                <div className="bg-[#111116] rounded-2xl shadow-lg p-6 mb-8">
                    <div className="flex flex-col md:flex-row gap-4">
                        <div className="relative flex-1">
                            <Search
                                className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"
                                size={20}
                            />
                            <input
                                type="text"
                                value={searchQuery}
                                onChange={(e) => setSearchQuery(e.target.value)}
                                placeholder="Search gigs by title, description, or poster..."
                                className="w-full pl-12 pr-4 py-3 bg-white/5 border border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-(--primary)/50 text-white"
                            />
                        </div>
                        <select
                            value={statusFilter}
                            onChange={(e) => setStatusFilter(e.target.value)}
                            className="px-4 py-3 bg-white/5 border border-white/10 rounded-xl focus:outline-none focus:ring-2 focus:ring-(--primary)/50 text-white"
                        >
                            <option value="all">All Status</option>
                            <option value="OPEN">Open</option>
                            <option value="CLOSED">Closed</option>
                            <option value="PENDING">Pending</option>
                        </select>
                    </div>
                </div>

                {/* Gigs Grid */}
                {loading ? (
                    <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {[...Array(6)].map((_, i) => (
                            <div key={i} className="animate-pulse bg-[#111116] rounded-2xl p-6 shadow-sm">
                                <div className="h-6 bg-white/5 rounded mb-3" />
                                <div className="h-4 bg-white/5 rounded mb-2" />
                                <div className="h-4 bg-white/5 rounded w-2/3" />
                            </div>
                        ))}
                    </div>
                ) : filteredGigs.length === 0 ? (
                    <div className="text-center py-20">
                        <Briefcase size={64} className="mx-auto text-slate-700 mb-4" />
                        <h3 className="font-bold text-white mb-2">
                            No gigs found
                        </h3>
                        <p className="text-slate-400">
                            Try adjusting your search or filters
                        </p>
                    </div>
                ) : (
                    <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredGigs.map((gig) => (
                            <motion.div
                                key={gig.id}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                className="bg-[#111116] rounded-2xl p-6 shadow-sm border border-white/10 hover:shadow-lg transition-all"
                            >
                                {/* Header */}
                                <div className="flex items-start justify-between mb-4">
                                    <h3 className="font-bold text-white line-clamp-2 flex-1">
                                        {gig.title}
                                    </h3>
                                    <span
                                        className={`ml-2 px-2 py-1 rounded-lg font-bold shrink-0 ${gig.status === "OPEN" ? "bg-green-500/20" : gig.status === "CLOSED" ? "bg-red-500/20" : "bg-amber-500/20 text-amber-400" }`}
                                    >
                                        {gig.status}
                                    </span>
                                </div>

                                {/* Description */}
                                <p className="text-slate-400 line-clamp-3 mb-4">
                                    {gig.description}
                                </p>

                                {/* Info */}
                                <div className="space-y-2 mb-4">
                                    <div className="flex items-center gap-2 text-slate-400">
                                        <DollarSign size={16} />
                                        <span className="font-semibold text-orange-500">
                                            ₹{gig.budget.toLocaleString()}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-2 text-slate-400">
                                        <Briefcase size={16} />
                                        <span>{gig._count.applications} applications</span>
                                    </div>
                                    {gig.deadline && (
                                        <div className="flex items-center gap-2 text-slate-400">
                                            <Calendar size={16} />
                                            <span>Due: {new Date(gig.deadline).toLocaleDateString()}</span>
                                        </div>
                                    )}
                                </div>

                                {/* Poster */}
                                <div className="pt-4 border-white/10 mb-4">
                                    <p className="text-slate-400">Posted by</p>
                                    <p className="font-medium text-white">
                                        {gig.poster.name || gig.poster.email}
                                    </p>
                                </div>

                                {/* Actions */}
                                <div className="flex gap-2">
                                    <Link
                                        href={`/gigs/${gig.id}`}
                                        className="flex-1 px-4 py-2 bg-white/5 rounded-lg hover:bg-white/10 transition-colors font-medium text-center flex items-center justify-center gap-2"
                                    >
                                        <Eye size={16} />
                                        View
                                    </Link>
                                    {gig.status === "PENDING" && (
                                        <>
                                            <button
                                                onClick={() => handleGigAction(gig.id, "approve")}
                                                className="flex-1 px-4 py-2 bg-green-500 rounded-lg hover:bg-green-600 transition-colors text-sm font-medium flex items-center justify-center gap-2"
                                            >
                                                <CheckCircle size={16} />
                                                Approve
                                            </button>
                                            <button
                                                onClick={() => {
                                                    if (confirm("Are you sure you want to reject this gig?")) {
                                                        handleGigAction(gig.id, "reject");
                                                    }
                                                }}
                                                className="flex-1 px-4 py-2 bg-red-500 rounded-lg hover:bg-red-600 transition-colors text-sm font-medium flex items-center justify-center gap-2"
                                            >
                                                <XCircle size={16} />
                                                Reject
                                            </button>
                                        </>
                                    )}
                                    {gig.status === "OPEN" && (
                                        <button
                                            onClick={() => {
                                                if (confirm("Are you sure you want to flag this gig?")) {
                                                    handleGigAction(gig.id, "flag");
                                                }
                                            }}
                                            className="flex-1 px-4 py-2 bg-amber-500 rounded-lg hover:bg-amber-600 transition-colors text-sm font-medium flex items-center justify-center gap-2"
                                        >
                                            <AlertTriangle size={16} />
                                            Flag
                                        </button>
                                    )}
                                </div>
                            </motion.div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

function StatCard({
    icon: Icon,
    label,
    value,
    color,
}: {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    icon: any;
    label: string;
    value: number;
    color: string;
}) {
    const colorClasses = {
        blue: "bg-blue-500/10 text-blue-400",
        green: "bg-green-500/10 text-green-400",
        red: "bg-red-500/10 text-red-400",
        amber: "bg-amber-500/10 text-amber-400",
    };

    return (
        <div className="bg-[#111116] rounded-xl p-6 shadow-sm border border-white/10">
            <div className="flex items-center gap-4">
                <div className={`p-3 rounded-lg ${colorClasses[color as keyof typeof colorClasses]}`}>
                    <Icon size={24} />
                </div>
                <div>
                    <p className="text-slate-400 font-medium">{label}</p>
                    <p className="font-black text-white">{value}</p>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import {
    GraduationCap, Plus, Search, Star, StarOff, CheckCircle, XCircle,
    Trash2, Edit3, Calendar, MapPin, DollarSign, Clock, Building2,
    Loader2, X, Save, ExternalLink,
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { toast } from "sonner";

interface Internship {
    id: string;
    title: string;
    description: string;
    company: string;
    skills: string | null;
    stipend: number | null;
    duration: string | null;
    location: string | null;
    tags: string | null;
    applicationLink: string | null;
    deadline: string | null;
    status: string;
    isFeatured: boolean;
    views: number;
    applyCount: number;
    createdAt: string;
}

const EMPTY_FORM = {
    title: "",
    description: "",
    company: "",
    skills: "",
    stipend: "",
    duration: "",
    location: "",
    deadline: "",
    status: "OPEN",
    isFeatured: false,
    applicationLink: "",
    tags: "",
};

export default function InternshipManagementPage() {
    const [internships, setInternships] = useState<Internship[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");
    const [statusFilter, setStatusFilter] = useState("all");
    const [stats, setStats] = useState({ total: 0, open: 0, pending: 0, featured: 0 });
    const [showModal, setShowModal] = useState(false);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [form, setForm] = useState(EMPTY_FORM);
    const [saving, setSaving] = useState(false);

    useEffect(() => { loadInternships(); }, []);

    const loadInternships = async () => {
        setLoading(true);
        try {
            const res = await fetch("/api/founder/internships");
            if (!res.ok) throw new Error("Failed");
            const data = await res.json();
            setInternships(data.internships || []);
            setStats(data.stats || { total: 0, open: 0, pending: 0, featured: 0 });
        } catch {
            toast.error("Failed to load internships");
        } finally {
            setLoading(false);
        }
    };

    const openNew = () => {
        setForm(EMPTY_FORM);
        setEditingId(null);
        setShowModal(true);
    };

    const openEdit = (internship: Internship) => {
        setForm({
            title: internship.title,
            description: internship.description,
            company: internship.company,
            skills: internship.skills || "",
            stipend: internship.stipend?.toString() || "",
            duration: internship.duration || "",
            location: internship.location || "",
            deadline: internship.deadline ? internship.deadline.slice(0, 10) : "",
            status: internship.status,
            isFeatured: internship.isFeatured,
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            applicationLink: (internship as any).applicationLink || "",
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            tags: (internship as any).tags || "",
        });
        setEditingId(internship.id);
        setShowModal(true);
    };

    const handleSave = async () => {
        if (!form.title || !form.company || !form.description) {
            toast.error("Title, company and description are required");
            return;
        }
        setSaving(true);
        try {
            const url = editingId ? `/api/founder/internships/${editingId}` : "/api/founder/internships";
            const method = editingId ? "PATCH" : "POST";
            const res = await fetch(url, {
                method,
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(form),
            });
            if (!res.ok) throw new Error("Failed");
            toast.success(editingId ? "Internship updated!" : "Internship created!");
            setShowModal(false);
            loadInternships();
        } catch {
            toast.error("Failed to save internship");
        } finally {
            setSaving(false);
        }
    };

    const handleAction = async (id: string, action: string) => {
        try {
            const res = await fetch(`/api/founder/internships/${id}`, {
                method: "PATCH",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ action }),
            });
            if (!res.ok) throw new Error("Failed");
            const labels: Record<string, string> = {
                approve: "Approved!", reject: "Rejected", feature: "Featured status toggled",
            };
            toast.success(labels[action] || "Done");
            loadInternships();
        } catch {
            toast.error("Action failed");
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Soft-delete this internship? It will be marked DELETED.")) return;
        try {
            const res = await fetch(`/api/founder/internships/${id}`, { method: "DELETE" });
            if (!res.ok) throw new Error("Failed");
            toast.success("Internship deleted");
            loadInternships();
        } catch {
            toast.error("Delete failed");
        }
    };

    const filtered = internships.filter((i) => {
        if (i.status === "DELETED") return false;
        const matchSearch = i.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
            i.company.toLowerCase().includes(searchQuery.toLowerCase());
        const matchStatus = statusFilter === "all" || i.status === statusFilter;
        return matchSearch && matchStatus;
    });

    const statusColor = (s: string) => {
        if (s === "OPEN") return "bg-green-500/20 text-green-400";
        if (s === "PENDING") return "bg-amber-500/20 text-amber-400";
        return "bg-red-500/20 text-red-400";
    };

    return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700 pb-10">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h1 className="md:text-4xl font-black text-white tracking-tight">
                        Internship <span className="text-orange-500">Management</span>
                    </h1>
                    <p className="text-slate-500 font-medium mt-1">Post, edit, approve & feature internship listings.</p>
                </div>
                <button
                    onClick={openNew}
                    className="px-5 py-2.5 bg-(--primary) rounded-xl font-bold text-sm flex items-center gap-2 hover:brightness-110 transition-colors shadow-lg shadow-(--primary)/20"
                >
                    <Plus size={16} /> New Internship
                </button>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                    { label: "Total", value: stats.total, color: "bg-blue-500/10 text-blue-400" },
                    { label: "Open", value: stats.open, color: "bg-green-500/10 text-green-400" },
                    { label: "Pending", value: stats.pending, color: "bg-amber-500/10 text-amber-400" },
                    { label: "Featured", value: stats.featured, color: "bg-purple-500/10 text-purple-400" },
                ].map((s) => (
                    <div key={s.label} className="bg-[#111116] rounded-2xl p-5 shadow-sm border-none">
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center mb-3 ${s.color}`}>
                            <GraduationCap size={20} />
                        </div>
                        <p className="font-bold uppercase tracking-wider text-slate-500">{s.label}</p>
                        <p className="font-black text-white">{s.value}</p>
                    </div>
                ))}
            </div>

            {/* Filters */}
            <div className="bg-[#111116] rounded-2xl p-5 shadow-sm flex flex-col md:flex-row gap-4">
                <div className="relative flex-1">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input
                        type="text"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder="Search by title or company..."
                        className="w-full pl-11 pr-4 py-3 bg-white/5 rounded-xl outline-none focus:ring-2 focus:ring-(--primary)/40 text-sm"
                    />
                </div>
                <select
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                    className="px-4 py-3 bg-white/5 rounded-xl outline-none focus:ring-2 focus:ring-(--primary)/40 text-sm font-medium"
                >
                    <option value="all">All Status</option>
                    <option value="OPEN">Open</option>
                    <option value="PENDING">Pending</option>
                    <option value="CLOSED">Closed</option>
                </select>
            </div>

            {/* Table */}
            <div className="bg-[#111116] rounded-3xl shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full">
                        <thead className="bg-white/5/60 border-white/10">
                            <tr>
                                {["Internship", "Company", "Stipend", "Deadline", "Status", "Actions"].map((h) => (
                                    <th key={h} className="px-6 py-4 font-black text-slate-500 uppercase tracking-wider">{h}</th>
                                ))}
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/10">
                            {loading ? (
                                [...Array(4)].map((_, i) => (
                                    <tr key={i} className="animate-pulse">
                                        {Array(6).fill(null).map((_, j) => (
                                            <td key={j} className="px-6 py-4"><div className="h-5 bg-white/5 rounded" /></td>
                                        ))}
                                    </tr>
                                ))
                            ) : filtered.length === 0 ? (
                                <tr><td colSpan={6} className="px-6 py-16 text-center">
                                    <GraduationCap size={48} className="mx-auto text-slate-700 mb-3" />
                                    <p className="text-slate-500 font-medium">No internships found</p>
                                </td></tr>
                            ) : filtered.map((internship) => (
                                <motion.tr
                                    key={internship.id}
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    className="hover:bg-white/5 transition-colors"
