                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <div>
                                                <p className="font-bold text-white line-clamp-1">{internship.title}</p>
                                                <p className="text-slate-500 line-clamp-1">{internship.skills || "No skills listed"}</p>
