                                                        initial={{ width: 0 }}
                                                        animate={{ width: `${value}%` }}
                                                        transition={{ duration: 1, ease: "easeOut" }}
                                                        className={`h-full ${color} rounded-full`}
                                                    />
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </Card>
                            </div>

                            {/* Strengths & Improvements */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                {/* Strengths */}
                                <Card className="border-white/10 bg-[#111116] p-8 rounded-[32px] shadow-lg">
                                    <h3 className="font-black text-white flex items-center gap-2 mb-5 text-base">
                                        <CheckCircle className="text-emerald-400" size={18} /> Top Strengths
                                    </h3>
                                    <ul className="space-y-3">
                                        {(activeInterview.feedback?.strengths || ["Well-structured logic flow", "Good attempt addressing all corner cases", "Clear technical focus"]).map((s: string, idx: number) => (
                                            <li key={idx} className="flex gap-3 text-sm font-semibold text-slate-300 leading-relaxed">
                                                <span className="text-emerald-400 shrink-0 mt-0.5">✔</span>
                                                <span>{s}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </Card>

                                {/* Improvements */}
                                <Card className="border-white/10 bg-[#111116] p-8 rounded-[32px] shadow-lg">
                                    <h3 className="font-black text-white flex items-center gap-2 mb-5 text-base">
                                        <AlertCircle className="text-amber-400" size={18} /> Target Improvement Areas
                                    </h3>
                                    <ul className="space-y-3">
                                        {(activeInterview.feedback?.improvements || ["Clarify complexity limits of algorithms", "Explain system design tradeoffs", "Provide code syntax samples"]).map((s: string, idx: number) => (
                                            <li key={idx} className="flex gap-3 text-sm font-semibold text-slate-300 leading-relaxed">
                                                <span className="text-amber-400 shrink-0 mt-0.5">➜</span>
                                                <span>{s}</span>
                                            </li>
                                        ))}
                                    </ul>
                                </Card>
                            </div>

                            {/* Options buttons */}
                            <div className="flex justify-center gap-4">
                                <Button
                                    onClick={returnToSetup}
                                    className="bg-white hover:bg-slate-200 text-slate-950 font-black px-8 h-14 rounded-2xl flex items-center gap-2 transition-all active:scale-95 shadow-md"
                                >
                                    <RefreshCw size={16} /> Start New Attempt
                                </Button>
                                <Button
                                    variant="outline"
                                    onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                                    className="border border-white/10 text-white font-black px-8 h-14 rounded-2xl hover:bg-white/5 active:scale-95 transition-all"
                                >
                                    View Chat Transcript
                                </Button>
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
}

"use client"

import { useEffect, useState } from "react"
import ProfileEditor from "@/components/profile/ProfileEditor"
import { Skeleton } from "@/components/ui/Skeleton"
import { ShieldCheck } from "lucide-react"

export default function StudentProfilePage() {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [profile, setProfile] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    async function fetchProfile() {
      try {
        const res = await fetch("/api/user/profile")
        if (!res.ok) throw new Error("Failed to fetch")
        const data = await res.json()

        // Ensure skills is an array for the editor
        const normalizedData = {
          ...data,
          skills: data.skills 
            ? (Array.isArray(data.skills) ? data.skills : data.skills.split(',').map((s: string) => s.trim()).filter(Boolean))
            : []
        }
        setProfile(normalizedData)
      } catch (err) {
        console.error(err)
      } finally {
        setLoading(false)
      }
    }
    fetchProfile()
  }, [])

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0A0F1E] space-y-10 p-10 max-w-7xl mx-auto">
        <Skeleton className="h-24 w-full rounded-2xl bg-white/5" />
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 md:gap-8">
            <Skeleton className="lg:col-span-2 h-[600px] rounded-3xl bg-white/5" />
            <div className="space-y-6">
                <Skeleton className="h-64 rounded-3xl bg-white/5" />
                <Skeleton className="h-96 rounded-3xl bg-white/5" />
            </div>
        </div>
      </div>
    )
  }

  if (!profile) {
    return (
      <div className="min-h-screen bg-[#0A0F1E] flex flex-col items-center justify-center p-6">
        <div className="bg-[#111116] border border-red-500/20 rounded-3xl p-10 text-center max-w-lg shadow-2xl">
          <ShieldCheck size={40} className="mx-auto text-red-400 mb-4" />
          <h2 className="font-bold text-white mb-2">Profile Missing</h2>
          <p className="text-slate-400">We couldn&apos;t load your profile data. Please refresh or contact support.</p>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[#0A0F1E]">
      <ProfileEditor profile={profile} />
    </div>
  )
}

