async function getTalentData(query?: string) {
  try {
    // Fetch top-rated candidates with their skills and reputation signals
    const candidates = await prisma.user.findMany({
      where: {
        role: "STUDENT",
        isVerified: true,
        ...(query ? {
          OR: [
            { skills: { contains: query, mode: "insensitive" } },
            { bio: { contains: query, mode: "insensitive" } },
            { college: { contains: query, mode: "insensitive" } },
          ]
        } : {}),
      },
      select: {
        id: true,
        name: true,
        full_name: true,
        image: true,
        avatar_url: true,
        college: true,
        branch: true,
        year: true,
        skills: true,
        bio: true,
        careerGoal: true,
        isVerified: true,
        github: true,
        linkedin: true,
        portfolio: true,
        userSkills: {
          select: { skill: { select: { name: true, category: true, color: true } } },
          take: 5,
        },
        reviewsReceived: {
          select: { rating: true },
          take: 50,
        },
        gigsPosted: {
          where: { status: "COMPLETED" },
          select: { id: true },
          take: 20,
        },
        endorsementsReceived: {
          select: { id: true },
          take: 30,
        },
      },
      take: 24,
      orderBy: { createdAt: "desc" },
    })

    // Compute reputation score for each candidate
    const ranked = candidates.map((c) => {
      const avgRating =
        c.reviewsReceived.length > 0
          ? c.reviewsReceived.reduce((a, r) => a + r.rating, 0) / c.reviewsReceived.length
          : 0
      const gigsCompleted = c.gigsPosted.length
      const endorsements = c.endorsementsReceived.length
      const reputationScore = Math.min(
        100,
        Math.round(gigsCompleted * 15 + endorsements * 5 + avgRating * 10)
      )
      const matchScore = query
        ? Math.floor(Math.random() * 25 + 70) // Simulated – replace with real cosine similarity
        : null
      return { ...c, reputationScore, avgRating, matchScore }
    })

    return ranked.sort((a, b) => b.reputationScore - a.reputationScore)
  } catch {
    return []
  }
}

