                                        <div className="flex-1 overflow-y-auto px-4 py-4 space-y-4 scroll-smooth">
                                            {messages.filter(m => !m.content.startsWith("__SUGGESTIONS__")).map((msg) => (
                                                <motion.div
                                                    key={msg.id}
                                                    initial={{ opacity: 0, y: 8 }}
