                                                                </span>
                                                            ) : (
                                                                <span className="whitespace-pre-wrap">{renderContent(msg.content)}</span>
                                                            )}
                                                        </div>
                                                        <span className="text-[9px] text-slate-600 mt-1 px-1">
                                                            {msg.timestamp.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
