'use client'
import { useState, useEffect, useRef, useMemo } from 'react'
import NextImage from 'next/image'
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { motion, AnimatePresence } from 'framer-motion'
import { 
  Search, Send, Plus, MoreVertical, 
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  Image as ImageIcon, Paperclip, Smile,
  Check, CheckCheck, Loader2, Phone, Video,

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  ArrowLeft, Users, ShieldCheck, Sparkles, UserCircle, MessageSquare
} from 'lucide-react'

import { createClient } from '@/lib/supabase/client'
import { format } from 'date-fns'
import { cn } from '@/lib/utils'
import { notify } from '@/lib/toast'

interface ConversationUser {
  id: string;
  name?: string;
  full_name?: string;
  avatar_url?: string;
  image?: string;
}

interface Conversation {
  id: string;
  user1: ConversationUser;
  user2: ConversationUser;
  last_message?: string;
  last_message_at?: string;
}

interface Message {
  id: string;
  conversation_id: string;
  sender_id: string;
  content: string;
  created_at: string;
  read_at?: string | null;
  status?: string;
}

interface MessagesLayoutProps {
  initialConversations: Conversation[]
  currentUserId: string
  initialActiveId?: string | null
}

export function MessagesLayout({ initialConversations, currentUserId, initialActiveId }: MessagesLayoutProps) {
  const supabase = createClient()
  const [mounted, setMounted] = useState(false)
  const [conversations, setConversations] = useState<Conversation[]>(initialConversations)
  const [activeId, setActiveId] = useState<string | null>(initialActiveId || null)
  const [messages, setMessages] = useState<Message[]>([])
  const [loadingMessages, setLoadingMessages] = useState(false)
  const [inputText, setInputText] = useState('')
  const [searchQuery, setSearchQuery] = useState('')
  // For presence mapping
  const [presence, setPresence] = useState<Record<string, unknown>>({})

  const scrollRef = useRef<HTMLDivElement>(null)

  useEffect(() => {

    setMounted(true)
  }, [])

  const activeConversation = useMemo(() => 
    conversations.find(c => c.id === activeId), 
  [conversations, activeId])

  // Get recipient info from conversation
  const recipient = useMemo(() => {
    if (!activeConversation) return null
    return activeConversation.user1.id === currentUserId ? activeConversation.user2 : activeConversation.user1
  }, [activeConversation, currentUserId])

  // Scroll to bottom
  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight
  }, [messages])

  // Subscriptions for Real-time
  useEffect(() => {
    if (!activeId) return


    setLoadingMessages(true)
    const fetchMessages = async () => {
      const { data } = await supabase
        .from('messages')
        .select('*')
        .eq('conversation_id', activeId)
        .order('created_at', { ascending: true })

      setMessages(data || [])
      setLoadingMessages(false)

      await supabase
        .from('messages')
        .update({ read_at: new Date().toISOString() })
        .eq('conversation_id', activeId)
        .neq('sender_id', currentUserId)
        .is('read_at', null)
    }
    fetchMessages()

    const channel = supabase
      .channel(`conv:${activeId}`)
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .on('postgres_changes' as any, { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'messages',
        filter: `conversation_id=eq.${activeId}`
      }, (payload: { new: Message, old: Message, eventType: string }) => {
        setMessages(prev => [...prev, payload.new])
        if (payload.new.sender_id !== currentUserId) {
            supabase.from('messages').update({ read_at: new Date().toISOString() }).eq('id', payload.new.id)
        }
      })
      .subscribe()

    return () => { supabase.removeChannel(channel) }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeId, currentUserId])

  // Presence Subscription
  useEffect(() => {
    const presenceChannel = supabase.channel('presence-sync')

    presenceChannel
      .on('presence', { event: 'sync' }, () => {
        const state = presenceChannel.presenceState()
        setPresence(state)
      })
      .subscribe(async (status) => {
        if (status === 'SUBSCRIBED') {
          await presenceChannel.track({
            userId: currentUserId,
            online_at: new Date().toISOString(),
          })
        }
      })

    return () => { supabase.removeChannel(presenceChannel) }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentUserId])

  const handleSendMessage = async (e?: React.FormEvent) => {
    e?.preventDefault()
    if (!inputText.trim() || !activeId) return

    const content = inputText.trim()
    setInputText('')

    // OPTIMISTIC UPDATE
    const tempId = Math.random().toString()
    const optimisticMsg = {
      id: tempId,
      conversation_id: activeId,
      sender_id: currentUserId,
      content,
      created_at: new Date().toISOString(),
      status: 'sending'
    }
    setMessages(prev => [...prev, optimisticMsg])

    const { data, error } = await supabase
      .from('messages')
      .insert({
        conversation_id: activeId,
        sender_id: currentUserId,
        content
      })
      .select()
      .single()

    if (error) {
      notify.error('Failed to send message')
      setMessages(prev => prev.filter(m => m.id !== tempId))
    } else {
      setMessages(prev => prev.map(m => m.id === tempId ? (data as Message) : m))
      // Update last message and re-sort list
      setConversations(prev => {
        const updated = prev.map(c => 
          c.id === activeId ? { ...c, last_message: content, last_message_at: data.created_at } : c
        );
        return [...updated].sort((a, b) => 
          new Date(b.last_message_at || 0).getTime() - new Date(a.last_message_at || 0).getTime()
        );
      });
    }
  }

  const filteredConversations = conversations.filter(c => {
    const r = c.user1.id === currentUserId ? c.user2 : c.user1
    return (r.full_name || r.name || '').toLowerCase().includes(searchQuery.toLowerCase())
  })

  // Return SSR-friendly skeleton until mounted
  if (!mounted) {
    return (
      <div className="flex h-[calc(100vh-4rem)] md:h-[calc(100vh-8rem)] bg-background border border-white/5 rounded-5xl overflow-hidden animate-pulse">
        <aside className="hidden md:flex w-96 bg-(--surface) border-white/5 flex-col p-8 gap-6">
          <div className="h-8 w-32 bg-(--surface-2) rounded-lg" />
          <div className="h-10 bg-(--surface-2) rounded-2xl" />
          {[1, 2, 3].map(i => <div key={i} className="h-20 bg-(--surface-2) rounded-2xl" />)}
        </aside>
        <main className="bg-background flex flex-col items-center justify-center">
           <div className="w-16 h-16 bg-(--surface-2) rounded-2xl mb-4" />
           <div className="h-4 w-48 bg-(--surface-2) rounded-lg" />
        </main>
      </div>
    )
  }

  return (
    <div className="flex h-[calc(100vh-4rem)] md:h-[calc(100vh-8rem)] bg-background border border-white/5 rounded-5xl overflow-hidden shadow-3xl">

      {/* Sidebar - Conversations List */}
      <aside className={cn(
        "w-full md:w-96 bg-(--surface) border-r border-white/5 flex flex-col md:flex",
        activeId && "hidden md:flex"
      )}>
        <div className="p-8 space-y-6">
          <div className="flex items-center justify-between">
             <h2 className="font-black text-white tracking-tight">Messages</h2>
             <button className="w-10 h-10 rounded-2xl bg-(--surface-2) border border-white/10 flex items-center justify-center text-indigo-400 hover:text-white transition-all">
                <Plus size={20} />
             </button>
          </div>

          <div className="relative group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-400 transition-colors" size={16} />
            <input 
              type="text" 
              placeholder="Search conversations..." 
              value={searchQuery}
              onChange={e => setSearchQuery(e.target.value)}
              className="w-full bg-white/2 border border-white/10 rounded-2xl py-3 pl-12 pr-4 font-bold text-white placeholder-slate-600 focus:outline-none focus:ring-1 focus:ring-indigo-500/50 transition-all"
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-4 pb-8 space-y-1 scrollbar-hide">
          {filteredConversations.map((conv) => {
            const r = conv.user1.id === currentUserId ? conv.user2 : conv.user1
            const isActive = activeId === conv.id
            const isOnline = presence[r.id]

            return (
              <button
                key={conv.id}
                onClick={() => setActiveId(conv.id)}
                className={cn(
                  "w-full flex items-center gap-4 p-4 rounded-3xl transition-all group relative",
                  isActive ? "bg-indigo-600 shadow-xl shadow-indigo-600/20" : "hover:bg-(--surface-2)"
                )}
              >
                <div className="relative shrink-0">
                  <div className="w-14 h-14 rounded-2xl overflow-hidden bg-slate-800 border-white/5 group-hover:scale-105 transition-transform">
                    {(r.avatar_url || r.image) ? (
                      <NextImage src={(r.avatar_url || r.image) as string} alt={r.name || 'User'} className="w-full h-full object-cover" width={56} height={56} />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center font-black text-indigo-400">
                        {(r.name as string)?.charAt(0) ?? 'U'}
                      </div>
                    )}
                  </div>
                  {Boolean(isOnline) && (
                    <div className="absolute -bottom-1 -right-1 w-4 h-4 rounded-full bg-emerald-500 border-[#111116] animate-in zoom-in" />
                  )}
                </div>

                <div className="flex-1 text-left min-w-0">
                  <div className="flex items-center justify-between mb-1">
                    <p className={cn("text-sm font-black truncate", isActive ? "text-white" : "text-white")}>
                      {r.full_name || r.name}
                    </p>
                    <span className={cn("text-[9px] font-black uppercase tracking-tight", isActive ? "text-white/60" : "text-slate-500")}>
                      {conv.last_message_at ? format(new Date(conv.last_message_at), 'H:mm') : ''}
                    </span>
                  </div>
                  <p className={cn("text-xs truncate font-medium", isActive ? "text-white/80" : "text-slate-400")}>
                    {conv.last_message || 'Start a conversation'}
                  </p>
                </div>
              </button>
            )
          })}
        </div>
      </aside>

      {/* Main Chat Window */}
      <main className={cn(
        "flex-1 flex flex-col bg-[#0d0d12] relative",
        !activeId && "hidden md:flex"
      )}>
        {activeConversation ? (
          <>
            {/* Header */}
            <header className="h-24 px-8 border-white/5 flex items-center justify-between bg-(--surface)/50 backdrop-blur-3xl">
              <div className="flex items-center gap-4">
                <button onClick={() => setActiveId(null)} className="md:hidden p-2 text-slate-400 hover:text-white">
                  <ArrowLeft size={20} />
                </button>
                <div className="relative">
                  <div className="w-12 h-12 rounded-2xl overflow-hidden bg-slate-800 border border-white/10">
                    {(recipient?.avatar_url || recipient?.image) ? (
                      <NextImage src={(recipient.avatar_url || recipient.image) as string} alt="Recipient" className="w-full h-full object-cover" width={48} height={48} />
                    ) : (
                       <div className="w-full h-full flex items-center justify-center font-black text-indigo-400">
                         {(recipient?.name as string)?.charAt(0) ?? 'U'}
                       </div>
                    )}
                  </div>
                  {Boolean(presence[recipient?.id ?? '']) && <div className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 rounded-full bg-emerald-500 border-[#111116]" />}
                </div>
                <div>
                  <h3 className="font-black text-white tracking-tight leading-tight">
                    {recipient?.full_name || recipient?.name}
                  </h3>
                  <p className="font-black uppercase tracking-widest text-emerald-500 opacity-80">
                    {presence[recipient?.id ?? ''] ? 'Online Now' : 'Last seen recently'}
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-2">
                 <button className="p-3 rounded-2xl bg-(--surface-2) border border-white/5 text-slate-400 hover:text-white transition-all"><Phone size={18} /></button>
                 <button className="p-3 rounded-2xl bg-(--surface-2) border border-white/5 text-slate-400 hover:text-white transition-all"><Video size={18} /></button>
                 <button className="p-3 rounded-2xl bg-(--surface-2) border border-white/5 text-slate-400 hover:text-white transition-all"><MoreVertical size={18} /></button>
              </div>
            </header>

            {/* Messages Area */}
            <div 
              ref={scrollRef}
              className="flex-1 overflow-y-auto p-8 space-y-6 scrollbar-thin scrollbar-thumb-white/5"
            >
              {loadingMessages ? (
                <div className="flex items-center justify-center h-full">
                  <Loader2 className="w-8 h-8 text-indigo-500 animate-spin" />
                </div>
              ) : (
                // eslint-disable-next-line @typescript-eslint/no-unused-vars
                messages.map((msg, i) => {
                  const isMe = msg.sender_id === currentUserId
                  return (
                    <motion.div
                      key={msg.id}
                      initial={{ opacity: 0, y: 10, scale: 0.95 }}
                      animate={{ opacity: 1, y: 0, scale: 1 }}
                      className={cn(
                        "flex flex-col max-w-[80%]",
                        isMe ? "ml-auto items-end" : "items-start"
                      )}
                    >
                      <div className={cn(
                        "px-6 py-4 rounded-4xl text-sm font-bold shadow-xl",
                        isMe 
                          ? "bg-indigo-600 text-white rounded-tr-none shadow-indigo-500/10" 
                          : "bg-(--surface-2) text-slate-200 border border-white/5 rounded-tl-none"
                      )}>
                        {msg.content}
                      </div>
                      <div className="flex items-center gap-2 mt-2 px-1">
                        <span className="font-bold text-slate-600 uppercase tracking-tight">
                          {format(new Date(msg.created_at), 'H:mm')}
                        </span>
                        {isMe && (
                           msg.read_at 
                            ? <CheckCheck className="w-3 h-3 text-indigo-400" />
                            : <Check className="w-3 h-3 text-slate-700" />
                        )}
                      </div>
                    </motion.div>
                  )
                })
              )}
            </div>

            {/* Input Area */}
            <div className="p-6 md:p-8 bg-(--surface)/80 backdrop-blur-3xl border-white/5">
              <form onSubmit={handleSendMessage} className="relative group">
                <div className="absolute inset-0 bg-indigo-500/5 blur-2xl rounded-full group-focus-within:bg-indigo-500/10 transition-all" />
                <div className="relative flex items-center bg-[#18181F] border border-white/5 group-focus-within:border-indigo-500/30 rounded-3xl p-1.5 shadow-2xl transition-all">
                  <button type="button" className="p-3 text-slate-500 hover:text-indigo-400 transition-colors">
                    <Paperclip size={20} />
                  </button>
                  <input 
                    type="text" 
                    value={inputText}
                    onChange={e => setInputText(e.target.value)}
                    placeholder="Write a message..."
                    className="flex-1 bg-transparent px-3 py-4 text-sm font-bold placeholder-slate-600 focus:outline-none"
                  />
                  <div className="flex items-center gap-1">
                    <button type="button" className="p-3 text-slate-500 hover:text-indigo-400 transition-colors hidden sm:block">
                      <Smile size={20} />
                    </button>
                    <button 
                      type="submit"
                      className="bg-indigo-600 hover:bg-indigo-700 text-white p-4 rounded-2xl shadow-xl shadow-indigo-600/20 active:scale-95 transition-all"
                    >
                      <Send size={18} fill="white" />
                    </button>
                  </div>
                </div>
              </form>
            </div>
          </>
        ) : (
          <div className="flex flex-col items-center justify-center p-12 text-center">
             <div className="relative mb-8 group">
                <div className="absolute inset-0 bg-indigo-500/20 blur-[60px] rounded-full" />
                <div className="relative w-24 h-24 rounded-4xl bg-(--surface) border border-white/10 flex items-center justify-center shadow-2xl">
                   <MessageSquare size={40} className="text-indigo-400" />
                </div>
             </div>
             <h3 className="font-black text-white tracking-tight mb-4">Select a Conversation</h3>
             <p className="max-w-xs text-slate-500 font-medium leading-relaxed">
               Pick a connection from the left to start collaborating on your next big project.
             </p>
             <div className="mt-10 flex gap-4">
                <div className="flex items-center gap-2 px-4 py-2 bg-(--surface-2) border border-white/10 rounded-xl font-black text-slate-400 uppercase tracking-widest">
                   <ShieldCheck size={14} className="text-emerald-500" />
                   End-to-End Encrypted
                </div>
                <div className="flex items-center gap-2 px-4 py-2 bg-(--surface-2) border border-white/10 rounded-xl font-black text-slate-400 uppercase tracking-widest">
                   <Sparkles size={14} className="text-indigo-400" />
                   AI Assisted Gigs
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  )
}

'use client'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import {
  Home, Briefcase, GraduationCap, Building2,
  MessageSquare, Users, Sparkles, UserCircle, LucideIcon
} from 'lucide-react'

interface TabItem {
  label: string
  href: string
  icon: LucideIcon
  highlight?: boolean
}

export function MobileTabBar({ userRole }: { userRole: string | null }) {
  const pathname = usePathname()

  const getTabs = (): TabItem[] => {
    if (!userRole) return []

    const common: TabItem[] = [
      { label: 'Network', href: '/network',  icon: Users },
      { label: 'Msgs',    href: '/messages', icon: MessageSquare },
    ]

    const role = userRole.toUpperCase()

    if (role === 'STUDENT') {
      return [
        { label: 'Home',  href: '/dashboard/student',            icon: Home },
        { label: 'Gigs',  href: '/gigs/find',                    icon: Briefcase },
        ...common,
        { label: 'Match', href: '/dashboard/student/smartmatch', icon: Sparkles, highlight: true },
      ]
    }

    if (role === 'CLIENT' || role === 'STARTUP') {
      return [
        { label: 'Home',     href: '/dashboard',  icon: Home },
        { label: 'Talent',   href: '/gigs/find',  icon: Briefcase },
        { label: 'Messages', href: '/messages',   icon: MessageSquare },
        { label: 'Post Gig', href: '/post-gig',   icon: Building2, highlight: true },
      ]
    }

    return common
  }

  const tabs = getTabs()
  if (!tabs.length) return null

  return (
    <div
      className="fixed bottom-0 left-0 right-0 z-50 lg:hidden pb-safe"
      style={{
        background: 'rgba(8,8,15,0.92)',
        backdropFilter: 'blur(24px)',
        WebkitBackdropFilter: 'blur(24px)',
        borderTop: '1px solid var(--border)',
      }}
    >
      <div className="flex items-center justify-around h-16 px-2">
        {tabs.map((tab) => {
          const isActive = pathname === tab.href || pathname.startsWith(tab.href + '/')
          const activeColor = tab.highlight ? 'var(--gold)' : 'var(--primary-light)'
          const inactiveColor = 'var(--text-3)'

          return (
            <Link
              key={tab.href}
              href={tab.href}
              className="flex flex-col items-center gap-1 min-w-[56px] py-1 transition-all"
              style={{ color: isActive ? activeColor : inactiveColor }}
            >
              <div
                className="p-2 rounded-xl transition-all"
                style={{
                  background: isActive
                    ? tab.highlight
                      ? 'rgba(245,158,11,0.12)'
                      : 'rgba(124,58,237,0.14)'
                    : 'transparent',
                }}
              >
                <tab.icon className="w-5 h-5" />
              </div>
              <span
                className="uppercase"
                style={{
                  fontSize: '9px',
                  fontWeight: 700,
                  letterSpacing: '0.12em',
                  fontFamily: 'var(--font-mono)',
                }}
              >
                {tab.label}
              </span>
            </Link>
          )
        })}
      </div>
    </div>
  )
}

'use client'

/**
 * NavbarClient — auth-aware, hydration-safe navbar.
 *
 * Architecture: server component (Navbar.tsx) passes initial user data as
 * props from an SSR fetch. This client component then subscribes to
 * Supabase's onAuthStateChange so the UI reacts instantly to login/logout
 * without a full-page refresh.
 *
 * Hydration safety:
 * - No Math.random() or Date.now() during render.
 * - Auth UI is gated behind `mounted` state so SSR HTML (logged-out)
 *   matches the initial client render before JS hydrates.
 */

import Link from 'next/link'
import Image from 'next/image'
import { usePathname, useRouter } from 'next/navigation'
import { useState, useEffect, useCallback } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  LayoutDashboard, Briefcase, Sparkles,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  MessageSquare, Users, Bell, Search, ChevronDown, Building2,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  LogOut, Settings, UserCircle, Plus, GraduationCap,
  ArrowUp,
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  Shield, CreditCard, Info, Menu, X, LucideIcon
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { ThemeToggle } from '@/components/ThemeToggle'
import NotificationsPopover from '@/components/NotificationsPopover'
import { createClient } from '@/lib/supabase/client'
import { SignOutButton } from '@/components/SignOutButton'

interface NavbarClientProps {
  userRole: string | null
  userId: string | null
  userName: string | null
  userAvatar: string | null
  unreadMessages: number
  pendingApplications: number
}

interface NavLink {
  label: string
  href: string
  icon: LucideIcon
  badge?: 'messages' | 'applications'
  highlight?: boolean
}

const getNavLinks = (role: string | null): NavLink[] => {
  if (!role) return []

  const common: NavLink[] = [
    { label: 'Post a Gig', href: '/post-gig', icon: Plus, highlight: true },
    { label: 'Network', href: '/network', icon: Users },
    { label: 'Messages', href: '/messages', icon: MessageSquare, badge: 'messages' },
  ]

  if (role === 'STUDENT') {
    return [
      { label: 'Home', href: '/dashboard/student', icon: LayoutDashboard },
      { label: 'Find Gigs', href: '/gigs/find', icon: Briefcase },
      { label: 'Internships', href: '/dashboard/student/internships', icon: GraduationCap },
      { label: 'SmartMatch', href: '/dashboard/student/smartmatch', icon: Sparkles, highlight: true },
      ...common,
    ]
  }

  if (role === 'CLIENT' || role === 'STARTUP') {
    return [
      { label: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
      { label: 'Browse Talent', href: '/gigs/find', icon: Briefcase },
      ...common,
    ]
  }

  if (role === 'FOUNDER') {
    return [
      { label: 'Founder Hub', href: '/dashboard/founder', icon: Shield },
      ...common,
    ]
  }

  return common
}

export function NavbarClient({
  userRole: initialRole,
  userId: initialUserId,
  userName: initialUserName,
  userAvatar: initialAvatar,
  unreadMessages,
  pendingApplications,
}: NavbarClientProps) {
  const pathname = usePathname()
  const router = useRouter()
  const supabase = createClient()

  // ── Hydration gate ──────────────────────────────────────────────────────
  // On the server, we always render the logged-OUT state to produce
  // a stable SSR HTML. After mount we sync to the real auth state.
  const [mounted, setMounted] = useState(false)

  // ── Live auth state — seeded from server props to avoid flash ─────────
  // Server component (Navbar.tsx) already fetched these safely server-side.
  // We use them as initial values so the first render is already correct.
  const [userId, setUserId] = useState<string | null>(initialUserId)
  const [userRole, setUserRole] = useState<string | null>(initialRole)
  const [userName, setUserName] = useState<string | null>(initialUserName)
  const [userAvatar, setUserAvatar] = useState<string | null>(initialAvatar)

  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false)
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false)
  const isScrolled = useScroll()

  // Close mobile menu on path changes safely (React 19 rules compliant)
  const [prevPathname, setPrevPathname] = useState(pathname)
  if (pathname !== prevPathname) {
    setPrevPathname(pathname)
    setIsMobileMenuOpen(false)
  }

  // ── Sync auth state from server props + Supabase listener ───────────────
  // Sync auth state. We deliberately do NOT query the User table here —
  // that triggers a Supabase RLS 403 from the client-side anon key.
  // Instead we read from auth.getUser() which is always permitted, and
  // fall back to the server-passed props that were already fetched safely.
  const syncUser = useCallback(async () => {
    const { data: { user }, error } = await supabase.auth.getUser()
    if (error || !user) {
      setUserId(null)
      setUserRole(null)
      setUserName(null)
      setUserAvatar(null)
      return
    }

    setUserId(user.id)
    // Use user_metadata populated by OAuth/auth provider — no DB round-trip needed
    const meta = user.user_metadata ?? {}
    setUserName(meta.full_name ?? meta.name ?? user.email?.split('@')[0] ?? null)
    setUserAvatar(meta.avatar_url ?? meta.picture ?? null)
    // Role comes from the server props (already correct) — don't overwrite unless we
    // can read it without 403. Keep existing userRole state from initial server props.
  }, [supabase])

  useEffect(() => {
    // 1. Mount flag — prevents auth UI flash on SSR
    // eslint-disable-next-line
    setMounted(true)

    // 2. Initial sync
    syncUser()

    // 3. Real-time listener — reacts to login/logout from any tab
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event) => {
      if (event === 'SIGNED_IN') syncUser()
      if (event === 'SIGNED_OUT') {
        setUserId(null)
        setUserRole(null)
        setUserName(null)
        setUserAvatar(null)
      }
      // Refresh server components (RSC) so Navbar.tsx re-fetches
      router.refresh()
    })

    return () => subscription.unsubscribe()
  }, [syncUser, supabase, router])

  const navLinks = getNavLinks(userRole)

  // ── Don't render nav on landing page ────────────────────────────────────
  if (pathname === '/') return null

  return (
    <>
      <nav
        className={cn(
          'fixed top-0 left-0 right-0 z-50 h-16 border-b transition-all duration-300',
          isScrolled
            ? 'backdrop-blur-3xl border-white/10'
            : 'border-white/5'
        )}
        style={{
          background: isScrolled
            ? 'rgba(8,8,15,0.92)'
            : 'rgba(8,8,15,1)',
        }}
      >
        <div className="max-w-7xl mx-auto px-6 h-full flex items-center justify-between gap-6">
          {/* Logo */}
          <Link href="/" className="flex items-center gap-2.5 shrink-0 group">
            <div className="relative w-8 h-8">
              <Image src="/logo-v2.jpg" alt="CampusConnect" width={32} height={32} className="rounded-lg object-contain" />
              <div className="absolute -top-0.5 -right-0.5 w-2.5 h-2.5 rounded-full" style={{ background: 'var(--accent)' }} />
            </div>
            <span
              className="text-lg hidden sm:block"
              style={{ fontFamily: "var(--font-heading)", fontWeight: 700, color: "var(--text)" }}
            >
              Campus<span className="text-gradient">Connect</span>
            </span>
          </Link>

          {/* Desktop Nav Links — only shown when logged in */}
          <div className="hidden lg:flex items-center gap-1.5 flex-1 justify-center">
            {mounted && userId && navLinks.map(link => {
              const isActive = pathname === link.href || pathname.startsWith(link.href + '/')
              const badgeCount = link.badge === 'messages' ? unreadMessages
                : link.badge === 'applications' ? pendingApplications : 0

              return (
                <Link
                  key={link.href}
                  href={link.href}
                  className={cn(
                    'relative flex items-center gap-2 px-4 py-2.5 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all duration-300',
                    link.highlight && !isActive && 'border',
                    link.highlight && isActive && 'border',
                    !link.highlight && !isActive && 'hover:bg-white/5',
                    !link.highlight && isActive && 'border',
                  )}
                  style={{
                    color: link.highlight
                      ? 'var(--gold)'
                      : isActive
                        ? 'var(--primary-light)'
                        : 'var(--text-2)',
                    background: link.highlight && isActive
                      ? 'rgba(245,158,11,0.12)'
                      : link.highlight && !isActive
                        ? 'rgba(245,158,11,0.05)'
                        : !link.highlight && isActive
                          ? 'rgba(124,58,237,0.12)'
                          : undefined,
                    borderColor: link.highlight && isActive
                      ? 'rgba(245,158,11,0.3)'
                      : link.highlight && !isActive
                        ? 'rgba(245,158,11,0.12)'
                        : !link.highlight && isActive
                          ? 'rgba(124,58,237,0.25)'
                          : undefined,
                  }}
                >
                  <link.icon className="w-4 h-4" />
                  <span>{link.label}</span>
                  {badgeCount > 0 && (
                    <span
                      className="absolute -top-1 -right-1 min-w-[18px] h-[18px] rounded-full text-[9px] font-black flex items-center justify-center px-1 border-2"
                      style={{ background: 'var(--primary)', borderColor: 'var(--bg)' }}
                    >
                      {badgeCount > 9 ? '9+' : badgeCount}
                    </span>
                  )}
                </Link>
              )
            })}
          </div>

          {/* Right Actions */}
          <div className="flex items-center gap-3">
            <button className="p-2.5 rounded-xl text-slate-500 hover:text-white hover:bg-white/5 transition-all">
              <Search className="w-4 h-4" />
            </button>

            <NotificationsPopover
              isOpen={isNotificationsOpen}
              onOpenChange={setIsNotificationsOpen}
            />

            <div className="hidden sm:block">
              <ThemeToggle />
            </div>

            {(userRole === 'CLIENT' || userRole === 'STARTUP') && mounted && userId && (
              <Link
                href="/post-gig"
                className="hidden xl:flex items-center gap-2 px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest active:scale-95 transition-all"
                style={{
                  background: "var(--grad-brand)",
                  boxShadow: "var(--shadow-glow-primary)",
                }}
                onMouseEnter={(e) => { (e.currentTarget as HTMLElement).style.boxShadow = "var(--shadow-btn-hover)" }}
                onMouseLeave={(e) => { (e.currentTarget as HTMLElement).style.boxShadow = "var(--shadow-glow-primary)" }}
              >
                <Plus className="w-3.5 h-3.5" />
                Post Gig
              </Link>
            )}

            {/* ── Auth UI — gated behind `mounted` to prevent hydration mismatch ── */}
            {!mounted ? (
              // Skeleton placeholder — same dimensions as auth buttons to avoid layout shift
              <div className="w-24 h-9 rounded-2xl bg-white/5 animate-pulse" />
            ) : userId ? (
              // ── LOGGED IN ──────────────────────────────────────────────
              <div className="relative group">
                <button className="flex items-center gap-3 p-1 rounded-2xl bg-white/5 border border-white/5 hover:border-white/10 transition-all">
                  <div className="w-9 h-9 rounded-xl overflow-hidden flex items-center justify-center border" style={{ background: 'rgba(124,58,237,0.15)', borderColor: 'var(--border)' }}>
                    {userAvatar ? (
                      <Image src={userAvatar} alt="Avatar" width={36} height={36} className="w-full h-full object-cover" referrerPolicy="no-referrer" unoptimized />
                    ) : (
                      <span className="font-black text-sm" style={{ color: "var(--primary-light)" }}>
                        {userName?.charAt(0)?.toUpperCase() ?? 'U'}
                      </span>
                    )}
                  </div>
                  <ChevronDown className="w-3.5 h-3.5 text-slate-500 group-hover:text-white transition-colors pr-2" />
                </button>

                {/* Dropdown */}
                <div className="absolute right-0 top-full mt-3 w-64 bg-[#111116] border border-white/10 rounded-3xl py-3 opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all duration-300 shadow-2xl overflow-hidden ring-1 ring-white/5">
                  <div className="px-5 py-4 border-b mb-2" style={{ borderColor: 'var(--border)' }}>
                    <p className="text-sm font-black truncate" style={{ color: 'var(--text)' }}>{userName ?? 'Authenticated User'}</p>
                    <p className="text-[10px] font-black uppercase tracking-widest mt-0.5" style={{ color: "var(--primary-light)" }}>{userRole}</p>
                  </div>

                  <DropdownItem href={userRole === 'STUDENT' ? '/dashboard/student/profile' : '/dashboard'} icon={UserCircle} label="Account Profile" />
                  <DropdownItem href={userRole === 'STUDENT' ? '/dashboard/student/settings' : (userRole === 'FOUNDER' ? '/dashboard/founder/settings' : '/dashboard')} icon={Settings} label="Settings" />

                  {userRole === 'STUDENT' && (
                    <>
                      <DropdownItem href="/dashboard/student/resume-analyzer" icon={Sparkles} label="Resume Analyzer" amber />
                      <DropdownItem href="/dashboard/student/career-copilot" icon={Sparkles} label="Career Copilot" amber />
                    </>
                  )}

                  {(userRole === 'CLIENT' || userRole === 'STARTUP') && (
                    <DropdownItem href="/dashboard" icon={Building2} label="Dashboard" amber />
                  )}

                  <div className="mt-3 pt-3 border-white/5 px-2">
                    <div className="flex items-center justify-center">
                      <SignOutButton />
                    </div>
                  </div>
                </div>
