"use client"

import { useRef, useState, useCallback } from "react"
import { motion, useSpring } from "framer-motion"
import { cn } from "@/lib/utils"

interface MagneticButtonProps {
    children: React.ReactNode
    className?: string
    variant?: "filled" | "outline" | "ghost"
    href?: string
    onClick?: () => void
    type?: "button" | "submit"
    disabled?: boolean
    "data-cursor"?: string
}

export default function MagneticButton({
    children,
    className,
    variant = "filled",
    href,
    onClick,
    type = "button",
    disabled,
    ...props
}: MagneticButtonProps) {
    const anchorRef  = useRef<HTMLAnchorElement>(null)
    const buttonRef  = useRef<HTMLButtonElement>(null)
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const [isHovered, setIsHovered] = useState(false)

    const x = useSpring(0, { stiffness: 300, damping: 30 })
    const y = useSpring(0, { stiffness: 300, damping: 30 })

    const handleMouseMove = useCallback((e: React.MouseEvent<HTMLElement>) => {
        const el = anchorRef.current ?? buttonRef.current
        if (!el) return
        const rect = el.getBoundingClientRect()
        const cx = rect.left + rect.width  / 2
        const cy = rect.top  + rect.height / 2
        x.set((e.clientX - cx) * 0.35)
        y.set((e.clientY - cy) * 0.35)
    }, [x, y])

    const handleMouseLeave = useCallback(() => {
        x.set(0)
        y.set(0)
        setIsHovered(false)
    }, [x, y])

    const baseStyles = cn(
        "relative inline-flex items-center justify-center gap-2 font-semibold rounded-xl transition-all duration-200 select-none whitespace-nowrap outline-none focus-visible:ring-2",
        "px-6 py-3 text-sm",
        variant === "filled" && [
            "text-white active:scale-[0.97]",
        ],
        variant === "outline" && [
            "border active:scale-[0.97]",
        ],
        variant === "ghost" && "active:scale-[0.97]",
        disabled && "opacity-50 cursor-not-allowed",
        className
    )

    // Inline styles per variant (CSS vars from design system)
    const variantStyle =
        variant === "filled"
            ? {
                background: "var(--grad-brand)",
                boxShadow: "var(--shadow-glow-primary)",
                color: "#fff",
            }
            : variant === "outline"
            ? {
                borderColor: "var(--border)",
                color: "var(--text-2)",
                background: "rgba(17,17,39,0.5)",
            }
            : {
                color: "var(--text-2)",
            }

    const handleHoverEnter = () => {
        setIsHovered(true)
    }

    const sharedMotionProps = {
        style: { x, y, ...variantStyle },
        onMouseMove: handleMouseMove,
        onMouseEnter: handleHoverEnter,
        onMouseLeave: handleMouseLeave,
        whileTap: { scale: 0.97 },
        "data-cursor": "button",
    } as const

    if (href) {
        return (
            <motion.a
                ref={anchorRef}
                href={href}
                className={baseStyles}
                {...sharedMotionProps}
            >
                {children}
            </motion.a>
        )
    }

    return (
        <motion.button
            ref={buttonRef}
            type={type}
            onClick={onClick}
            disabled={disabled}
            className={baseStyles}
            {...sharedMotionProps}
        >
            {children}
        </motion.button>
    )
}

"use client"

import { useEffect, useRef } from "react"
import { ReactLenis } from "lenis/react"
import type { LenisRef } from "lenis/react"
import type Lenis from "lenis"
import { gsap } from "gsap"
import { ScrollTrigger } from "gsap/ScrollTrigger"

if (typeof window !== "undefined") {
    gsap.registerPlugin(ScrollTrigger)
}

export default function SmoothScrollProvider({ children }: { children: React.ReactNode }) {
    // Lenis instance provided by ReactLenis
    const lenisRef = useRef<LenisRef>(null)

    useEffect(() => {
        // Connect Lenis to GSAP ticker for perfect synchronization with ScrollTrigger
        const update = (time: number) => {
            // GSAP time is in seconds, Lenis expects milliseconds
            lenisRef.current?.lenis?.raf(time * 1000)
        }

        gsap.ticker.add(update)
        gsap.ticker.lagSmoothing(0)

        return () => {
            gsap.ticker.remove(update)
        }
    }, [])

    // Ensure ScrollTrigger updates on scroll
    useEffect(() => {
        const lenis = lenisRef.current?.lenis;
        if (!lenis) return;

        const onScroll = () => {
            ScrollTrigger.update();
        };

        lenis.on('scroll', onScroll);
        return () => {
            lenis.off('scroll', onScroll);
        };
    }, []);

    return (
        <ReactLenis
            root
            ref={lenisRef}
            autoRaf={false}
            options={{
                duration: 1.5, // slightly longer for a luxurious feel
                easing: (t: number) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
                orientation: "vertical",
                gestureOrientation: "vertical",
                smoothWheel: true,
                wheelMultiplier: 1.05,
                touchMultiplier: 2,
            }}
        >
            {children}
        </ReactLenis>
    )
}

import prisma from '@/lib/prisma';
import { computeUserEmbedding, cosineSimilarity } from './embeddings';

export interface FeedPost {
  id: string;
  content: string;
  authorId: string;
  author: { name: string | null; image: string | null; role: string };
  createdAt: Date;
  _count: { likes: number };
  feedScore: number;
  signals: {
    recency: number;
    engagement: number;
    social: number;
    semantic: number;
  };
}

export interface FeedGig {
  id: string;
  title: string;
  description: string;
  budget: number;
  tags: string | null;
  createdAt: Date;
  poster: { name: string | null; image: string | null };
  _count: { applications: number };
  feedScore: number;
}

// ─── Recency decay (half-life = 24 hours) ─────────────────────────────────────
function recencyScore(createdAt: Date): number {
  const ageHours = (Date.now() - new Date(createdAt).getTime()) / (1000 * 60 * 60);
  return Math.exp(-ageHours / 24); // exponential decay
}

// ─── Engagement score (log scale to prevent viral monopoly) ───────────────────
function engagementScore(likeCount: number, appCount = 0): number {
  return Math.log1p(likeCount + appCount * 2) / Math.log1p(100);
}

// ─── Assemble personalized post feed ─────────────────────────────────────────
export async function assemblePersonalizedFeed(userId: string, limit = 20): Promise<FeedPost[]> {
  // Fetch user context
  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: {
      following: { select: { followingId: true } },
      userSkills: { include: { skill: { select: { name: true } } } }
    }
  });
  if (!user) throw new Error('User not found');

  const followingIds = new Set(user.following.map((f: any) => f.followingId));

  // Fetch recent posts
  const posts = await prisma.post.findMany({
    where: { status: 'OPEN' },
    include: {
      author: { select: { name: true, image: true, role: true } },
      _count: { select: { likes: true } }
    },
    orderBy: { createdAt: 'desc' },
    take: 100
  });

  // Try to get user embedding for semantic scoring
  let userVector: number[] | null = null;
  try {
    userVector = await computeUserEmbedding(userId);
  } catch {
    // Fallback: no semantic signal
  }

  // Score each post
  const scored = posts.map((post: any) => {
    const recency = recencyScore(post.createdAt);
    const engagement = engagementScore(post._count.likes);
    const social = followingIds.has(post.authorId) ? 0.3 : 0;
    const isSelf = post.authorId === userId ? -0.5 : 0; // don't surface own posts heavily

    // Semantic: embed post content and compare — skip if no vector
    // (Pre-computed post vectors would be ideal; for now use fallback)
    const semantic = 0;

    const feedScore = (
      recency * 0.35 +
      engagement * 0.25 +
      social * 0.30 +
      semantic * 0.10 +
      isSelf
    );

    return {
      ...post,
      feedScore,
      signals: { recency, engagement, social, semantic }
    } as FeedPost;
  });

  return scored
    .sort((a: FeedPost, b: FeedPost) => b.feedScore - a.feedScore)
    .slice(0, limit);
}

// ─── Assemble personalized gig feed ──────────────────────────────────────────
export async function assemblePersonalizedGigFeed(userId: string, limit = 15): Promise<FeedGig[]> {
  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: { applications: { select: { gigId: true } } }
  });
  if (!user) throw new Error('User not found');

  const appliedIds = new Set(user.applications.map((a: any) => a.gigId));

  const gigs = await prisma.gig.findMany({
    where: { status: 'OPEN' },
    include: {
      poster: { select: { name: true, image: true } },
      gigSkills: { include: { skill: { select: { name: true } } } },
      _count: { select: { applications: true } }
    },
    orderBy: { createdAt: 'desc' },
    take: 100
  });

  // User skill set for matching
  const userSkills = (user.skills || '').toLowerCase().split(',').map((s: string) => s.trim());

  // Get user vector
  let userVector: number[] | null = null;
  try {
    userVector = await computeUserEmbedding(userId);
  } catch {/* noop */}

  // Get gig embeddings in bulk
  const gigIds = gigs.map((g: any) => g.id);
  const gigEmbeddings = await (prisma as any).gigEmbedding.findMany({
    where: { gigId: { in: gigIds } }
  });
  const gigEmbMap = new Map<string, number[]>();
  gigEmbeddings.forEach((ge: any) => gigEmbMap.set(ge.gigId, ge.vector));

  const scored = gigs.map((gig: any) => {
    const recency = recencyScore(gig.createdAt);
    const engagement = engagementScore(0, gig._count.applications);

    // Skill overlap score
    const gigSkillNames = gig.gigSkills.map((gs: any) => gs.skill.name.toLowerCase());
    const overlap = gigSkillNames.filter((s: string) => userSkills.some((us: string) => us && s.includes(us))).length;
    const skillMatch = Math.min(overlap / Math.max(gigSkillNames.length, 1), 1.0);

    // Semantic vector match
    let semantic = 0;
    if (userVector && gigEmbMap.has(gig.id)) {
      semantic = Math.max(0, cosineSimilarity(userVector, gigEmbMap.get(gig.id)!));
    }

    // Penalty: already applied
    const appliedPenalty = appliedIds.has(gig.id) ? -0.4 : 0;

    const feedScore = (
      recency * 0.20 +
      engagement * 0.10 +
      skillMatch * 0.35 +
      semantic * 0.35 +
      appliedPenalty
    );

    return {
      id: gig.id,
      title: gig.title,
      description: gig.description,
      budget: gig.budget,
      tags: gig.tags,
      createdAt: gig.createdAt,
      poster: gig.poster,
      _count: gig._count,
      feedScore
    } as FeedGig;
  });

  return scored
    .sort((a: FeedGig, b: FeedGig) => b.feedScore - a.feedScore)
    .slice(0, limit);
}

// ─── Combined feed assembler ──────────────────────────────────────────────────
export async function assembleHomeFeed(userId: string) {
  const [posts, gigs] = await Promise.all([
    assemblePersonalizedFeed(userId, 10),
    assemblePersonalizedGigFeed(userId, 5)
  ]);

  return { posts, gigs };
}

import prisma from '@/lib/prisma';
import { computeUserEmbedding, findTopN, Candidate } from './embeddings';

export async function rankGigsForUser(userId: string) {
    const user = await prisma.user.findUnique({ where: { id: userId }, include: { applications: true } });
    if (!user) throw new Error("User not found");

    const userVector = await computeUserEmbedding(userId);

    const gigs = await prisma.gig.findMany({
        where: { status: "OPEN" }
    });

    // We also need gig embeddings
    const gigEmbeddings = await (prisma as any).gigEmbedding.findMany({
        where: { gigId: { in: gigs.map((g: any) => g.id) } }
    });

    const gigEmbMap = new Map();
    gigEmbeddings.forEach((ge: any) => gigEmbMap.set(ge.gigId, ge.vector));

    const appliedGigIds = new Set(user.applications.map((a: any) => a.gigId));

    const candidates: Candidate[] = gigs.map((g: any) => ({
        ...g,
        id: g.id,
        vector: gigEmbMap.get(g.id) as number[],
        hasApplied: appliedGigIds.has(g.id)
    })).filter((g: any) => g.vector); // only rank gigs that have vectors

    const boostFn = (gig: Candidate, baseScore: number): number => {
        let boost = 0;
        const gigSkills = (gig.tags || '').toLowerCase();
        const userSkills = (user.skills || '').toLowerCase();

        // +0.25 -> gig skills overlap with target skills
        if (gigSkills && userSkills && userSkills.includes(gigSkills.split(',')[0])) boost += 0.25;
        // +0.20 -> category match
        if (gig.tags && user.careerGoal && user.careerGoal.includes(gig.tags)) boost += 0.20;
        // +0.05 -> freshness
        if (gig.createdAt && (Date.now() - new Date(gig.createdAt).getTime()) < 24 * 60 * 60 * 1000) boost += 0.05;
        // -0.30 -> user already applied
        if (gig.hasApplied) boost -= 0.30;

        return boost;
    };

    return findTopN(userVector, candidates, 20, boostFn);
}

import prisma from '@/lib/prisma';
import { computeUserEmbedding, findTopN, Candidate } from './embeddings';

export async function rankStudentsForUser(queryUserId: string) {
    const queryUser = await prisma.user.findUnique({ where: { id: queryUserId } });
    if (!queryUser) throw new Error("Query user not found");

    const queryVector = await computeUserEmbedding(queryUserId);

    // Fetch all other users
    const users = await prisma.user.findMany({
        where: { id: { not: queryUserId }, role: "STUDENT" }
    });

    const userEmbeddings = await (prisma as any).userEmbedding.findMany({
        where: { userId: { in: users.map((u: any) => u.id) } }
    });

    const userEmbMap = new Map();
    userEmbeddings.forEach((ue: any) => userEmbMap.set(ue.userId, ue.vector));

    const candidates: Candidate[] = users.map((u: any) => ({
        ...u,
        id: u.id,
        vector: userEmbMap.get(u.id) as number[]
    })).filter((u: any) => u.vector);

    const boostFn = (student: Candidate, baseScore: number): number => {
        let boost = 0;
        // +0.20 -> same college
        if (student.college && queryUser.college && student.college === queryUser.college) boost += 0.20;

        // Simplified boosts
        // +0.10 -> both show available (using isVerified or basic proxy since available is not standard here)
        if (student.isVerified && queryUser.isVerified) boost += 0.10;

        return boost;
    };

    return findTopN(queryVector, candidates, 10, boostFn);
}

import { getOpenAI } from './client';
const pdfParse = require('pdf-parse');
import * as mammoth from 'mammoth';

export interface ResumeData {
  skills: string[];
  tools: string[];
  domains: string[];
  education: { degree: string; field: string; college: string; year: string }[];
  projects: { name: string; description: string; techStack: string[]; url: string }[];
  experience: { role: string; company: string; duration: string; description: string }[];
  languages: string[];
  certifications: string[];
  keywords: string[];
  experienceLevel: 'fresher' | 'junior' | 'intermediate' | 'senior';
  summary: string;
}

export async function parseResume(fileUrl: string): Promise<ResumeData> {
  let fileBuffer: Buffer;

  if (fileUrl.startsWith('http')) {
      const response = await fetch(fileUrl, {
          headers: {
              'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
              'Accept': 'application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain'
          }
      });

      if (!response.ok) throw new Error(`Failed to download resume: ${response.status} ${response.statusText}`);

      const contentType = response.headers.get('content-type') || '';
      if (contentType.includes('text/html')) {
          throw new Error("Security block detected: The file provider is blocking automated access. Please download the file and upload it manually.");
      }

      const arrayBuffer = await response.arrayBuffer();
      fileBuffer = Buffer.from(arrayBuffer);
  } else {
      // In case it's a local path or pre-downloaded buffer, but usually it's a url
      throw new Error("Invalid file URL provided.");
  }

  let text = '';
  const lowerUrl = fileUrl.toLowerCase();

  // Extract raw text
  if (lowerUrl.includes('.pdf')) {
      const pdfParseModule = (pdfParse as any).default || pdfParse;
      const pdfResult = await (typeof pdfParseModule === 'function' ? pdfParseModule(fileBuffer) : pdfParseModule.default(fileBuffer));
      text = pdfResult.text || '';
  } else if (lowerUrl.includes('.docx')) {
      const result = await mammoth.extractRawText({ buffer: fileBuffer });
      text = result.value || '';
  } else {
      text = fileBuffer.toString('utf-8');
  }

  if (!text.trim()) {
      throw new Error("Could not extract any text from the document.");
  }

  // Send to OpenAI
  const apiKey = process.env.OPENAI_API_KEY || "";
  const isGroq = apiKey.startsWith("gsk_");
  const model = isGroq ? 'llama-3.3-70b-versatile' : (process.env.AI_CHAT_MODEL || 'gpt-4o-mini');

  const openai = getOpenAI();
  const response = await openai.chat.completions.create({
      model: model,
      response_format: { type: 'json_object' },
      messages: [
          {
              role: 'system',
              content: `Extract structured data from this resume.
Return JSON with:
- skills: string[] (tech + soft skills)
- tools: string[] (software, frameworks, platforms)
- domains: string[] (web, mobile, AI, design, etc.)
- education: { degree, field, college, year }[]
- projects: { name, description, techStack[], url }[]
- experience: { role, company, duration, description }[]
- languages: string[]
- certifications: string[]
- keywords: string[] (20 most important career keywords)
- experienceLevel: fresher|junior|intermediate|senior
- summary: string (2 sentence professional summary)
Return ONLY valid JSON. No preamble.`
          },
          {
              role: 'user',
              content: text
          }
      ]
  });

  const content = response.choices[0].message.content;
  if (!content) {
      throw new Error("OpenAI returned empty response");
  }

  try {
      return JSON.parse(content) as ResumeData;
  } catch (e) {
      throw new Error("Failed to parse JSON response from OpenAI");
  }
}

export async function generateProfileBio(resumeData: ResumeData): Promise<string> {
    const promptData = `
    Level: ${resumeData.experienceLevel}
    Skills: ${resumeData.skills.join(', ')}
    Experience: ${resumeData.experience.map(e => e.role + ' at ' + e.company).join(', ')}
    Summary: ${resumeData.summary}
    `;

    const apiKey = process.env.OPENAI_API_KEY || "";
    const isGroq = apiKey.startsWith("gsk_");
    const model = isGroq ? 'llama-3.3-70b-versatile' : (process.env.AI_CHAT_MODEL || 'gpt-4o-mini');

    const openai = getOpenAI();
    const response = await openai.chat.completions.create({
        model: model,
        messages: [
            {
                role: 'system',
                content: "Write a 3-sentence first-person professional bio for a student with this background. Make it confident, specific, and authentic. Avoid generic phrases. Max 150 words."
            },
            {
                role: 'user',
                content: promptData
            }
        ]
    });

    return response.choices[0].message.content?.trim() || "";
}

export function suggestSkills(currentSkills: string[], resumeText: string): string[] {
    // A more advanced version would use an LLM, but a simple NLP matching or a fast AI request can be used.
    // Let's implement an AI call for it using a small prompt to be robust, 
    // or just rely on the resumeData.skills parsed earlier. 
    // For now, let's use a quick extraction via OpenAI just to find differences.
    // Note: returning string[] as per requirements. We'll do a synchronous simulated find, or actually, 
    // the prompt says suggestSkills is a sync `string[]`. This means it cannot use OpenAI if it's sync.
    // Wait, the interface in prompt is `suggestSkills(currentSkills[], resumeText): string[]` without Promise.
    // We'll use NLP compromise to find technical skills simply, or regex.

    // Quick heuristic: find common developer keywords in text that aren't in currentSkills
    const textLower = resumeText.toLowerCase();
    const commonTechSkills = ['react', 'node.js', 'typescript', 'javascript', 'python', 'java', 'c++', 'aws', 'docker', 'kubernetes', 'figma', 'ui/ux', 'sql', 'mongodb', 'express', 'next.js', 'vue', 'angular', 'django', 'spring boot'];

    const currentLower = new Set(currentSkills.map(s => s.toLowerCase()));
    const suggested: string[] = [];

    for (const skill of commonTechSkills) {
        if (textLower.includes(skill) && !currentLower.has(skill)) {
            // Check if it's a standalone word roughly
            const regex = new RegExp(`\\b${skill.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'i');
            if (regex.test(textLower)) {
                suggested.push(skill);
            }
        }
    }

    return suggested.slice(0, 10);
}
